-- 065_replace_corrupted_decision_11_2014_listing_delisting_rules_with_clean_text_and_enable_governance_scope.sql
--
-- إصلاح جذرى لعيب "المادة الواحدة الضخمة" — السابع والأخير من دفعة الـ7
-- قوانين المؤكَّدة بهذا العيب (تقرير التدقيق 2026-09-26)، وهو الأكبر
-- بفارق كبير: قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 11 لسنة
-- 2014 بشأن قواعد قيد وشطب الأوراق المالية بالبورصة المصرية وتعديلاته.
--
-- law_no=11، law_year=2014، kind='board_decision' (قرار مجلس إدارة، وليس
-- قانوناً، فلا توجد مواد إصدار منفصلة — article_suffix_order=-1 غير
-- مستخدم فى هذه الوثيقة).
--
-- ===== المصدر والمنهجية =====
-- المصدر: نسخة FRA الرسمية المُجمَّعة والمحدَّثة حتى أغسطس 2026
-- ("النسخة النهائية لقواعد القيد - أغسطس 2026"، 66 صفحة، منشأة بـAdobe
-- InDesign بتاريخ 2026-09-07، طبقة نص موجودة لكنها مُستخدَمة للتحقق
-- الثانوى فقط لمشاكل إعادة ترتيب الحروف العربية RTL المعروفة). استُخرج
-- النص بقراءة بصرية مباشرة لكل الصفحات الـ66 (عرض 300 DPI)، مع تحقق مزدوج
-- عبر OCR (tesseract حزمة اللغة العربية) على نفس صور الصفحات. رُصِد ذيل
-- تعديلات الوثيقة نفسها ليؤكِّد أن آخر تعديل مُدرَج هو قرار مجلس إدارة
-- الهيئة رقم 195 لسنة 2026 بتاريخ 2026/8/19 (استبدال المادة 38 بالكامل
-- وإضافة مادتين جديدتين 39 مكرراً و39 مكرراً 1) — وهو ما يطابق البحث
-- المستقل الذى تم قبل قبول هذه النسخة كمصدر (تم رفض نسخة أقدم مؤرَّخة حتى
-- أكتوبر 2023 لثبوت وجود تعديلات لاحقة غير مُستوعبة فيها: قرار 148/2024
-- وقرار 195/2026).
--
-- ===== هيكل الوثيقة =====
-- 57 مادة أساسية (article_no من 1 إلى 57، article_suffix_order=0) +
-- 21 مادة "مكرر" مُدرَجة لاحقاً (article_suffix_order=1 أو 2 بحسب
-- الاصطلاح المتبع فى الهجرات السابقة)، بإجمالى 78 صفاً. لا توجد أى مواد
-- ملغاة صراحة فى النص الحالى (المادة 68 التى أُلغيت فى نسخة 2023 القديمة
-- لم تعد موجودة أصلاً بأى ترقيم فى هذه النسخة المُحدَّثة — البنية أُعيد
-- ترقيمها بالكامل وتنتهى عند المادة 57 "توفيق الأوضاع").
--
-- المادة (38) الحالية أدناه هى النص الساري بعد استبدالها بالكامل بقرار
-- مجلس إدارة الهيئة رقم 195 لسنة 2026 بتاريخ 2026/8/19 (تعاملات
-- الداخليين)، والمادتان (39 مكرراً) و(39 مكرراً 1) مضافتان بذات القرار.
--
-- ===== الأثر =====
-- (أ) استبدال صف المتن التالف الوحيد (142,158 حرفاً تحت مادة 1 واحدة)
-- بـ78 صفاً نظيفاً، (ب) تأكيد governance_scope=true، (ج) الإبقاء على
-- enacted_at='2014-01-22' كما هو مسجَّل بالفعل (COALESCE لا يغيّره إن كان
-- موجوداً).
--
-- قابلة لإعادة التشغيل بأمان (idempotent): حذف الصف التالف مشروط بعدد
-- صفوف =1 فقط، وكل إدراج محمى بـON CONFLICT (law_id, article_no,
-- article_suffix_order) DO NOTHING.

BEGIN;

DO $fix065$
DECLARE
  v_law_id uuid;
  v_article_count int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision';

  IF v_law_id IS NULL THEN
    RAISE WARNING '[065] decision 11/2014 (kind=board_decision) غير موجود فى laws — غير متوقَّع، تخطّى هذه الهجرة';
    RETURN;
  END IF;

  SELECT count(*) INTO v_article_count FROM articles WHERE law_id = v_law_id;

  IF v_article_count = 1 THEN
    DELETE FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0;
    RAISE NOTICE '[065] decision 11/2014: أُزيل الصف التالف القديم (مادة 1 واحدة تحوى المتن الكامل)';
  ELSIF v_article_count = 78 THEN
    RAISE NOTICE '[065] decision 11/2014: 78 صفاً موجودة بالفعل — سبق إصلاحه، تخطّى الحذف';
  ELSE
    RAISE WARNING '[065] decision 11/2014: عدد مواد غير متوقَّع (%) — راجع يدوياً', v_article_count;
  END IF;
END
$fix065$;

-- ===== إدراج المواد =====

WITH ins0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1a$مادة 1$t1a$, $t1b$تعد هذه القواعد الإطار القانوني المنظم لضوابط وإجراءات قيد واستمرار قيد وشطب الأوراق المالية بالبورصة، وتسري هذه القواعد على كافة أنواع الأوراق المالية المقيدة بالبورصة كالأسهم والسندات وصكوك التمويل ووثائق صناديق الاستثمار وشهادات الإيداع المصرية وغير ذلك من الأوراق المالية.

ولا تخل الاحكام الواردة بهذه القواعد بكافة المتطلبات الأخرى الواجب على الشركات أو الجهات المقيد لها أوراق مالية الالتزام بها طبقاً للأحكام الواردة بالتشريعات الخاضعة لها تلك الشركات أو الجهات وعلى الأخص؛ قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم (159) لسنة 1981، وقانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992.$t1b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins0;

WITH ins1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 1, NULL, $t2a$مادة 1 مكرر$t2a$, $t2b$يجوز قيد الأسهم المصدرة من الشركات المصرية والأجنبية وشهادات الإيداع المصرية بجداول البورصة المصرية قيداً مؤقتاً قبل استيفاء البنود (1، 2، 3) من المادتين (7) أو (9)، أو الحد الأدنى لعدد حملة شهادات الإيداع ونسبة الشهادات حرة التداول على النحو المنصوص عليه بالمادة (16) أو البند (د) من المادة (15) من هذه القواعد بحسب الأحوال، وعلى الشركات المقيد أوراقها المالية إتمام إجراءات التسجيل لدى الهيئة وفقاً للقواعد التي يحددها مجلس إدارة الهيئة والتقدم للبورصة لتنفيذ الطرح أو بدء التداول على تلك الأسهم أو الشهادات بحسب الأحوال خلال ستة أشهر من تاريخ القيد، ويجوز مد هذه المهلة بموافقة الهيئة في الحالات التي تقدرها بناءً على المبررات والخطة الزمنية التي تقدمها الشركة. ويعتبر القيد المؤقت كأن لم يكن في حالة انتهاء المهلة المشار إليها دون تنفيذ الطرح واستيفاء شروط ومتطلبات القيد.

كما يجوز للهيئة مد مهلة إتمام إجراءات الطرح للشركات السابق قيد أسهمها بالبورصة قبل العمل بقرار مجلس إدارة الهيئة رقم (122) لسنة 2017 الصادر بشأن تعديل قواعد قيد وشطب الأوراق المالية بالبورصة المصرية، وذلك وفقاً لما تقدمه هذه الشركات للهيئة من مبررات وخطة زمنية ووفقاً لما تقدره الهيئة حسب موقف كل شركة. ويعتبر قيد أسهم هذه الشركات كأن لم يكن في حالة انتهاء المهلة المشار إليها دون تنفيذ الطرح واستيفاء شروط ومتطلبات القيد.

ومع عدم الإخلال بأحكام القانون (159) لسنة 1981 والقانون (95) لسنة 1992، لا تسري الالتزامات الواردة بالأبواب الثالث والرابع والخامس من هذه القواعد - فيما عدا الالتزامات المنصوص عليها بالبنود من (1 إلى 4) من المادة (48) من هذه القواعد - على الشركات التي تم قيد أوراقها المالية وفقاً لأحكام هذه المادة لحين استيفاء هذه الشركات لمتطلبات القيد والطرح وبدء التداول على أوراقها المالية.

* مضافة بموجب قرار مجلس إدارة الهيئة رقم (124) لسنة 2015، وتم تعديل المسمى وتعديل المادة بموجب قرارات المجلس رقم 96 بتاريخ 2017/7/25 ورقم (11) بتاريخ 2017/1/29 ورقم (73) لسنة 2022 بتاريخ 2022/8/31، ثم تعديل المادة بأكملها بموجب قرار المجلس رقم 26 بتاريخ 2026/1/22.$t2b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins1;

WITH ins2 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t3a$مادة 2$t3a$, $t3b$يضع مجلس إدارة البورصة الإجراءات التنفيذية للقواعد المنصوص عليها بهذا القرار ويجوز أن تتضمن هذه الإجراءات تخصيص جدول مستقل ضمن جداول الأوراق المالية المصرية لأسهم الشركات الصغيرة والمتوسطة.

ويعمل بالإجراءات التنفيذية السابقة فور اعتمادها من الهيئة.$t3b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins2;

WITH ins3 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 1, NULL, $t4a$مادة 2 مكرر$t4a$, $t4b$تتولى البورصة متابعة مدى التزام الشركات والجهات المقيد لها أوراق مالية بجداولها بأحكام قواعد قيد وشطب الأوراق المالية، وبوجه خاص متطلبات استمرار القيد والالتزامات الدورية المقررة بهذه القواعد وبالتشريعات ذات الصلة.

وللبورصة في سبيل ذلك متابعة ورصد حالات عدم التزام الشركات المقيدة، وعلى الأخص ما يتعلق بما يلي:

1- إتاحة استخدام الأنظمة الإلكترونية لحضور اجتماعات الجمعية العامة وإثبات إجراءاتها والتصويت عليها عن بعد.
2- التزام الشركات باستخدام أسلوب التصويت التراكمي عند انتخاب أعضاء مجلس الإدارة.
3- الالتزام بمواعيد إرسال ونشر القوائم المالية الدورية والسنوية.
4- التزام الشركات بتضمين تشكيل مجلس الإدارة أعضاء مستقلين والتأكد من نسبة تمثيل المرأة على النحو الوارد بهذه القواعد.
5- التزام الشركات بإعداد تقارير لجنة المراجعة ولجنة الترشيحات والمكافآت وغيرها من اللجان المنبثقة عن مجلس الإدارة، متى كان ذلك مقرراً.
6- التزام الشركات باستيفاء الإفصاحات المتعلقة بالممارسات البيئية والمجتمعية والحوكمة المتعلقة بالاستدامة (ESG)، أو الإفصاحات المتعلقة بالآثار المالية للتغيرات المناخية (TCFD) بتقريرها السنوي المعد من مجلس إدارتها والمرفق بالقوائم المالية السنوية والمنصوص عليها بقرار مجلس إدارة الهيئة رقم (108) لسنة 2021.
7- أي التزامات أخرى مقررة لاستمرار القيد وفقاً لأحكام هذه القواعد أو الإجراءات التنفيذية الصادرة تنفيذاً لها.

وتقوم البورصة بموافاة الهيئة بتقرير نصف سنوي، يتضمن بياناً تفصيلياً بالشركات غير الملتزمة بقواعد القيد أو استمرار القيد، موضحاً به اسم الشركة وطبيعة المخالفة وأساسها القانوني ومدة استمرار المخالفة والإجراءات التي اتخذتها البورصة حيال كل حالة.

كما تقوم البورصة بإخطار الهيئة فوراً بحالات المخالفات الجسيمة التي ترتكبها الشركات والجهات المقيدة بجداولها والتي من شأنها الإضرار بحقوق المتعاملين أو التأثير الجوهري على كفاءة وشفافية السوق، وذلك لاتخاذ ما تراه الهيئة من إجراءات بشأنها.

* مضافة بموجب قرار مجلس إدارة الهيئة رقم 26 بتاريخ 2026/1/22.$t4b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins3;

WITH ins4 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t5a$مادة 3$t5a$, $t5b$على البورصة موافاة الهيئة بأية بيانات أو مستندات تطلبها تتعلق بالأوراق المالية المقيدة بها.$t5b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins4;

WITH ins5 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t6a$مادة 4 (تعريفات)$t6a$, $t6b$يقصد بالألفاظ والعبارات التالية المعنى المبين قرين كل منها:

الأوراق المالية: يقصد بالأوراق المالية في تطبيق أحكام هذه القواعد الأسهم والسندات وصكوك التمويل ووثائق صناديق الاستثمار وشهادات الإيداع المصرية وغير ذلك من الأوراق المالية.

عضو مجلس الإدارة المستقل: هو عضو مجلس الإدارة غير التنفيذي من ذوي الخبرة الذي لا تربطه بالشركة أو بأي من أعضاء الإدارة التنفيذية بها أو مراقب حساباتها أو شركتها الأم أو أي من شركاتها التابعة أو الشقيقة، أي رابطة عمل أو علاقة تعاقدية أو أي علاقة قد تؤدي إلى وجود منفعة مادية من شأنها التأثير على قراراته، وليس زوجاً أو من أقارب الدرجة الثانية لأي من هؤلاء.

وتنتفي صفة الاستقلالية عن عضو مجلس الإدارة المستقل على وجه الأخص في الحالات الآتية:

1- إذا كان العضو أو أي من أقاربه حتى الدرجة الثانية يعمل أو سبق له العمل في الشركة أو الإدارة التنفيذية العليا بها أو بالشركة الأم أو الشركة التابعة لها خلال السنتين السابقتين لتاريخ شغله لعضوية مجلس الإدارة.
2- إذا كان للعضو أو أحد أقاربه حتى الدرجة الثانية مصلحة مباشرة أو غير مباشرة في العقود التي تُعقد مع الشركة أو شركاتها التابعة خلال السنتين السابقتين لتاريخ شغله لعضوية مجلس الإدارة، ما لم تكن هذه التعاقدات بناءً على مناقصة أو ممارسة ودون شروط تفضيلية.
3- إذا قدم أعمالاً استشارية، أو كان مراقب حسابات أو شريكاً له أو موظفاً لديه، أو قدم أي خدمات أخرى، سواء للشركة أو أي من الشركات الأم أو الشركات التابعة أو الشقيقة خلال السنتين السابقتين لتاريخ شغله لعضوية مجلس الإدارة.
4- إذا بلغت ملكيته كشخص طبيعي سواء بمفرده أو مع مجموعته المرتبطة في رأس مال الشركة أو حقوق التصويت بها نسبة تجاوز (1%).
5- إذا شغل عضوية مجلس إدارة الشركة كعضو مستقل لمدة ست سنوات متصلة، مع عدم جواز إعادة تعيينه بهذه الصفة إلا بعد مرور ثلاث سنوات على انتهاء عضويته بمجلس الإدارة.

وفي جميع الأحوال، لا تتأثر صفة استقلالية عضو مجلس الإدارة حال كونه عضو مجلس إدارة مستقل في الشركة الأم أو في إحدى الشركات التابعة التي تمتلك فيها الشركة الأم نسبة لا تقل عن (51%) من أسهمها وبشرط موافقة مساهمي الأقلية للشركة التابعة على ذلك.

الأطراف ذات العلاقة: يقصد بالأطراف ذات العلاقة كل من تربطهم بالشركة علاقة مباشرة أو غير مباشرة في إحدى الحالات التالية:
أ. السيطرة على الشركة أو الوقوع معها تحت سيطرة مشتركة.
ب. ملكية نسبة من الأسهم أو حقوق التصويت تمنحه القدرة على التأثير الفعال على قراراتها.
ج. عضوية مجلس إدارة أو شغل منصب المدير التنفيذي في الشركة طالبة القيد أو في شركتها القابضة أو في إحدى شركاتها التابعة أو الشقيقة.
د. الوقوع تحت السيطرة الكاملة أو السيطرة المشتركة أو تحت التأثير المباشر لأشخاص يملكون نسبة من الأسهم أو حقوق التصويت تمنحهم القدرة على التأثير الفعال.
ه. أن يكون للطرف ذو العلاقة نظاماً مستقلاً عن الشركة خاص بالمزايا أو معاشات التقاعد لصالح العاملين في الشركة أو أي شركة لها علاقة بالشركة.

الداخليين: يقصد بالداخليين في تطبيق أحكام هذه القواعد أعضاء مجلس إدارة الشركة أو شركتها القابضة وشركاتها التابعة والشقيقة أو المسيطرة عليها وممثليهم وأزواجهم وأولادهم القصر، وكذلك كل من في مكنته الاطلاع على أياً من المعلومات الداخلية للشركة وأزواجهم وأولادهم القصر.

المساهم الرئيسي: يقصد بالمساهم الرئيسي أي مساهم يملك 10% فأكثر من أسهم رأسمال الشركة سواء بصورة مباشرة أو غير مباشرة من خلال المجموعات والأطراف المرتبطة.

مساهمي الأقلية: كل مساهم يمتلك بمفرده أو مع مجموعته المرتبطة نسبة من أسهم الشركة أو حقوق التصويت بها لا تمكنه من السيطرة على قرارات مجلس إدارة الشركة أو جمعيتها العامة أو التحكم في السياسات المالية أو التشغيلية للشركة، ولا يملك أغلبية حقوق التصويت في اجتماعات الجمعية العامة للشركة.

الأسهم حرة التداول: يقصد بالأسهم حرة التداول جميع الأسهم المتاحة للتعامل عليها شراء أو بيعاً دون قيود، ويتم حسابها بعد أن يستبعد من أسهم الشركة المقيدة في جداول البورصة ما يلي:

1- الأسهم المملوكة لشركات قطاع الأعمال القابضة في شركاتها التابعة المقيد لها أسهم بالبورصة.
2- الأسهم المملوكة للمساهمين الرئيسيين وذلك وفقاً للنسب التالية:
- 100% من الأسهم الواجب الاحتفاظ بها وفقاً لهذه القواعد.
- 100% في غير حالات الاحتفاظ الواردة بهذه القواعد، ويشترط لاستبعاد 100% أن يحدث تعامل خلال عام سابق على تاريخ الاحتساب.
3- الأسهم المملوكة للمؤسسين خلال فترة الحظر الواردة بالمادة 45 من القانون 159 لسنة 1981 سواء عند التأسيس أو زيادة رأس المال، وذلك كله ما لم تكن ضمن أسهم المساهمين الرئيسيين.
4- أسهم الخزينة.
5- أسهم ضمان عضوية مجلس الإدارة في حالة اشتراط النظام الأساسي للشركة ذلك وذلك طوال فترة العضوية.
6- الأسهم المملوكة للمساهمين الملزمين بموجب اتفاقات أو عقود بالاحتفاظ بنسبة أو عدد من أسهم الشركة لمدة معينة وذلك خلال تلك المدة.

المجموعة المرتبطة: يقصد بالمجموعة المرتبطة كل مجموعة من الأطراف تكون خاضعة للسيطرة الفعلية لنفس الأشخاص الطبيعيين أو لذات الأشخاص الاعتبارية أو يجمع بينهما اتفاق على التنسيق عند التصويت في اجتماعات الجمعية العامة للشركة أو في مجلس إدارتها.

الشركات الصغيرة والمتوسطة: يقصد بالشركات الصغيرة والمتوسطة في تطبيق أحكام هذه القواعد الشركات المساهمة التي لا يقل رأس مالها المصدر والمدفوع عن مليون جنيه ويقل رأسمالها المصدر والمدفوع عن 100 مليون جنيه أو ما يعادلها من العملات الأجنبية عند تقديم طلب القيد لأول مرة ويقل رأس مالها المصدر والمدفوع عن 200 مليون جنيه أو ما يعادلها من العملات الأجنبية بعد ذلك.

الطرح بالبورصة: عرض لبيع أسهم شركة بالبورصة المصرية سواء كانت أسهم قائمة أو من خلال زيادة رأس المال أو بغرض توفيق الأوضاع أو لتوسيع قاعدة الملكية.

نشرة الطرح أو تقرير الإفصاح بغرض الطرح: نموذج بيانات ومعلومات تعتمده الهيئة بغرض طرح الأوراق المالية للبيع بالبورصة المصرية سواء في طرح عام أو خاص.

التصويت التراكمي: يقصد به منح كل مساهم عدداً من الأصوات مساوياً لعدد الأسهم التي يملكها للتصويت بها في اختيار أعضاء مجلس إدارة الشركة، وللمساهم أن يمنح كل الأصوات التي يملكها لمرشح واحد أو أكثر من مرشح، وذلك بما يسمح بالتمثيل النسبي في عضوية مجلس الإدارة كلما أمكن ذلك.

التمثيل النسبي لرأس المال في مجلس إدارة الشركة: يقصد به ضمان تمثيل حد أدنى من نسبة رأس المال في عضوية مجلس إدارة الشركة بما لا يجاوز مقعداً بمجلس الإدارة لكل (10%) من أسهم الشركة.

الهيئة: الهيئة العامة للرقابة المالية.

القيد المؤقت: يقصد به قيد أسهم الشركات غير المستوفاة للحد الأدنى لنسبة الأسهم المراد طرحها وعدد المساهمين (أو حملة شهادات الإيداع) ونسبة الأسهم (أو شهادات الإيداع) حرة التداول على النحو المنصوص عليه بهذه القواعد.

- قانون رقم 159 لسنة 1981: قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة.
- قانون رقم 8 لسنة 1997: قانون ضمانات وحوافز الاستثمار.
- قانون رقم 95 لسنة 1992: قانون سوق رأس المال.
- القانون رقم 14 لسنة 2012: مرسوم بقانون بشأن التنمية المتكاملة في شبه جزيرة سيناء.

* تم تعديل تعريف عضو مجلس الإدارة المستقل الوارد بالمادة (4) بموجب قرار المجلس رقم (35) بتاريخ 2016/3/27، ثم بموجب قرار المجلس رقم (177) بتاريخ 2023/8/30. تم إضافة تعريف مساهمي الأقلية بموجب قرار مجلس إدارة الهيئة رقم (26) بتاريخ 2026/1/22. تم تعديل تعريف الأسهم حرة التداول بموجب قرار مجلس إدارة الهيئة رقم (149) بتاريخ 2022/10/27. تم تعديل تعريف الشركات الصغيرة والمتوسطة بموجب قرار مجلس إدارة الهيئة رقم (13) بتاريخ 2018/3/27. تم إضافة تعريف الطرح بالبورصة ونشرة الطرح والتصويت التراكمي والتمثيل النسبي بموجب قرارات المجلس رقم 122 لسنة 2017 بتاريخ 2017/10/29 وما تلاها. تم إضافة تعريف القيد المؤقت بموجب قرار المجلس رقم 26 لسنة 2026 بتاريخ 2026/1/22.$t6b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins5;

WITH ins6 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t7a$مادة 5$t7a$, $t7b$يتم قيد الأوراق المالية بجداول البورصة بناء على طلب من الجهة المصدرة بقرار من لجنة قيد الأوراق المالية التي تتشكل بقرار من مجلس إدارة البورصة. وتقوم إدارة البورصة بإخطار الهيئة بجميع القرارات الصادرة عن اللجنة خلال ثلاثة أيام عمل من تاريخ صدورها.$t7b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins6;

WITH ins7 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, $t8a$مادة 6$t8a$, $t8b$يشترط للقيد بجداول البورصة استيفاء الشروط العامة الآتية:

1. أن تكون الأوراق المالية مقيدة بنظام الإيداع والقيد المركزي.
1 (مكرر). ألا يزيد رأس المال المرخص به للشركة الراغبة في قيد أوراقها المالية على خمسة أمثال رأس المال المصدر.
2. ألا يتضمن النظام الأساسي للجهة المصدرة أو شروط الإصدار أية قيود على تداول الأوراق المالية المطلوب قيدها مع عدم الإخلال بالقيود الواردة بالتشريعات المنظمة لبعض الأنشطة أو مناطق جغرافية معينة.
3. أن يتم القيد لجميع الأوراق المالية المصدرة من ذات النوع، وكذا قيد الإصدارات التالية وحق الأولوية في الاكتتاب وفقاً للأحكام الواردة بهذه القواعد.
4. أن تلتزم الشركة طالبة القيد بإنشاء موقع إلكترونياً على شبكة المعلومات الدولية لنشر أي قيد من أوراقها المالية فور قيدها وقبل بدء التداول عليها وتقرير مراقبي حساباتها ونشر القوائم المالية السنوية والدورية والإيضاحات المتممة لها وما يجب على الشركات إخطارها به من بين ما تحددها إدارة البورصة من البيانات والمعلومات وغيرها من الشركات إخطارها بها وفقا لهذه القواعد، وذلك دون الإخلال بمتطلبات الإفصاح الواردة بهذه القواعد وبديلاً عن ذلك يجوز أن تنشر عن ذلك على موقع تخصصه البورصة لهذا الغرض.
5. أن يتم تقديم طلب القيد ومرفقاته من خلال الممثل القانوني للجهة طالبة القيد أو من خلال وكيل قيد معتمد لدى البورصة وفقا للضوابط التي تحددها البورصة لإجراءات التنفيذية لهذه القواعد.
6. أن تبرم الجهة طالبة قيد أوراقها المالية عقداً مع البورصة ينظم حقوق والتزامات كل منهما بما في ذلك التزامات الجهة طالبة القيد المترتبة على مخالفة قواعد القيد وإجراءات القيد أو نصوص القيد أو نصوص العقد.
7. وجوب استخدام أسلوب التصويت التراكمي عند انتخاب أعضاء مجلس الإدارة بما يسمح بالتمثيل النسبي للمساهمين في عضوية مجلس الإدارة، شريطة إمكان ذلك وتطبيق أسلوب واحدة جولة انتخاب وتطبيق التصويت التراكمي على جميع المرشحين بما فيهم أعضاء مجلس الإدارة المستقلين ونسبة تمثيل المرأة. (13)
8. ألا يقل نسبة تمثيل المرأة في مجلس إدارة الشركة عن 25% أو عضوين على الأقل. (14)
9. حظر الجمع بين منصب رئيس مجلس الإدارة ومنصب العضو المنتدب أو الرئيس التنفيذي للشركة. وللهيئة الاستثناء المؤقت من هذا الشرط في ضوء المبررات التي تقدمها الشركة وتقبلها الهيئة. (15)
10. الانضمام لعضوية صندوق حماية المستثمر من المخاطر غير التجارية. (16)
11. التعهد بإسناد دراسة وفحص طلبات الترشح لعضوية مجلس الإدارة - وبصفة خاصة بالنسبة لمرشحي المستقلين - إلى لجنة الترشيحات والمكافآت، وعلى اللجنة دراسة أهلية المرشحين واستقلاليتهم وفقاً لمعايير الحوكمة الصادرة عن الهيئة وأحكام القانون رقم 159 لسنة 1981 ولائحته التنفيذية باستبعاد غير المؤهلين، وإصدار توصياتها بشأن ذلك مسبباً بما يكون منها رأياً في مجلس الإدارة لإبداء الرأي بشأنها وعرضها على مجلس الإدارة لإبداء الرأي بشأنها وعرضها تمهيداً للعرض على الجمعية العامة لاتخاذ ما تراه مناسباً.
12. الالتزام بتضمين تقرير مجلس الإدارة المعروض على الجمعية العامة السنوي الذاتي لأداء مجلس الإدارة متضمناً قياس مستوى فاعلية مشاركة كل عضو في اجتماعات المجلس، ودوره في دعم أعمال المجلس. وتوصيات لجنة الترشيحات والمكافآت بشأن نتائج هذا التقييم الذاتي.
13. الالتزام بالإخطار المسبق للهيئة في حال تغيير رغبة الشركة في تغيير مراقب حساباتها بسجلات الهيئة على أن يتضمن الإخطار مبررات التغيير وخطة التسليم والتسلم تتضمن فترة زمنية معقولة بين مراقب الحسابات المراد تغييره ومراقب الحسابات المراد تعيينه. وللهيئة مناقشة مبررات تغيير مراقب الحسابات وموافقة مراقب الحسابات المقترح تعيينه قبل عرض قرار تغيير مراقب الحسابات على السلطة المختصة، وتلتزم الشركة بالإفصاح للجمعية العامة عن ملاحظاتها بشأن تغيير مراقب الحسابات، وللهيئة نشر مقترح نتيجة فحص مراقب الحسابات على شاشة الإعلانات بالبورصة المصرية.
14. وجود نظام إلكتروني مالي ومحاسبي كاف، وبيئة رقابية فعالة للنظام المالي والمحاسبي.

ويجوز إجراء تحقق ميداني على المركز الرئيسي للشركة أو فروعها للتحقق من استيفاء متطلبات القيد وذلك بالتنسيق بين الهيئة والبورصة المصرية.$t8b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins7;

WITH ins8 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, $t9a$مادة 7$t9a$, $t9b$يشترط لقيد أسهم الشركات المصرية ما يأتي:

1- ألا تقل نسبة الأسهم المراد طرحها عن (25%) من إجمالي الأسهم المقيدة للشركة، أو ربع في الألف من رأس المال، أو أسهم تعادل قيمتها (1%) من رأس المال السوقي حر التداول بالبورصة. ويقصد بالطرح في تطبيق هذا الشرط عرض أسهم الشركة للبيع بالبورصة بناءً على نشرة طرح أو تقرير الإفصاح بغرض الطرح معتمد من الهيئة يتضمن ما انتهت إليه دراسة المستشار المالي المستقل بتحديد القيمة العادلة للسهم وتقرير مراقب الحسابات بشأن هذه الدراسة وفقاً لمعيار المراجعة المصرية ذات الصلة، على أن يتم نشر أي منهما وفقاً للنموذج المعتمد من مجلس إدارة الهيئة.
2- ألا يقل عدد المساهمين بالشركة بعد الطرح عن 300 مساهم مع مراعاة أن تكون الأسهم المخصصة موزعة في ضوء الضوابط التي تحددها البورصة بهدف التحقق من عدم صورية الطرح.
وتعتبر الشركة مستوفية للشرطين السابقين إذا كان هيكل مساهميها عند تقديم طلب القيد يتضمن 25% على الأقل من رأسمالها أو ربع في الألف من رأس المال السوقي حر التداول بالبورصة لا يقل عن 10% من أسهم الشركة لمساهمين بخلاف المؤسسين والمساهمين الرئيسيين، وبها عدد مساهمين لا يقل عن 300 مساهم، وألا تكون الأسهم المتضمنة في تلك النسبة مرهونة، على أن يتم نشر تقرير إفصاح على الشركة على النسب المشار إليها بالبند (1).
3- ألا تقل نسبة حرة التداول عن (10%) في إجمالي أسهم الشركة، أو 1/8 في الألف من رأس المال حر التداول بالبورصة، أو أسهم الشركة قيمتها نصف في المائة من رأس المال السوقي حر التداول بالبورصة.
4- ألا يقل عدد الأسهم المصدرة المطلوب قيدها عن 5 مليون سهم.
5- أن تقدم الشركة طالبة القيد القوائم المالية لسنتين ماليتين سابقتين على طلب القيد، على أن تكون هذه القوائم معدة وفقاً لمعايير المحاسبة المصرية وتمت مراجعتها وفقاً لمعايير المراجعة المصرية بواسطة أحد مراقبي الحسابات المقيدين بسجل الهيئة العامة ومصدق عليها من الجمعية العامة للشركة والموثق محضرها لدى الجهة الإدارية المختصة.
6- أن يكون رأس المال المصدر مدفوعاً بالكامل ولا يقل عن مائة مليون جنيه مصري أو ما يعادلها من العملات الأجنبية وذلك من واقع قوائم مالية سنوية أو آخر قوائم مالية دورية مرفقاً بها تقرير مراجعة شامل من مراقب الحسابات ومصدق عليها من الجمعية العامة للشركة.
7- تقديم تعهدات بألا يقل نسبة احتفاظ المساهمين الذين يمتلكون نسبة أكثر من (10%) فأكثر من أسهم رأس مال الشركة و/أو من يحلون محلهم من باقي المساهمين بالشركة عن (51%) من الأسهم المملوكة لهم في رأس مال الشركة حال توافرها، وإذا كان إجمالي الأسهم المصدر الشركة المحتفظ بها وفقاً لذلك نسبته أقل من (25%) من أسهم رأس مال الشركة يتم استكمال نسبة (25%) من مساهمات أعضاء مجلس الإدارة ومؤسسي الشركة أو غيرهم من مساهمي الشركة وذلك بشرط مرور لا تقل عن (24) ميلادياً شهراً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ الطرح بالنسبة للشركات التي طرحت أسهمها للاكتتاب العام في سوق الطرح قبل القيد في سوق الأوراق المالية الأساسية بذات النسبة السابقة على الاحتفاظ بها على أي زيادة تالية في رأس مال الشركة لذات الفترة، وذلك فيما عدا الأسهم المجانية.
ويجوز - بعد موافقة الهيئة والجمعية العامة العادية للشركة - أن تنتقل ملكية الأسهم المحتفظ بها - جزء منها أو بالكامل - خلال مدة الاحتفاظ المشار إليها في حال كون المشتري إليها بنك أو شركة تأمين أو صندوق استثمار مباشر أو أحد الكيانات المتخصصة في الاستثمار أو شخص اعتباري أو شخص له خبرة وسابقة أعمال متميزة في مجال نشاط الشركة، وبشرط أن يتعهد بالالتزام بشرط الاحتفاظ حتى نهاية المدة المقررة.
8- ألا تقل نسبة صافي الربح قبل خصم الضرائب على آخر سنة مالية سابقة على طلب القيد عن (5%) من رأس المال المدفوع المطلوب قيده، على أن يكون صافي أرباح الشركة قبل خصم الضرائب متولد من ممارسة نشاطها الفعلي المحقق لغرضها الوارد بنظامها الأساسي وبشرط ألا تقل نسبة صافي الربح قبل خصم الضرائب بحسابه على أساس سنوي عن (5%) من القوائم المالية الدورية المطلوب قيدها المثبت بها رأس المال - في حالة الانتهاء من إعدادها - عن السنوات التالية من إصدارها، وألا تقل حقوق المساهمين عن رأس المال المرجحاً بالمدة، وذلك مع واقع آخر قوائم مالية سنوية أو دورية سابقة على تاريخ طلب القيد عن سنوية مالية سنوية أو دورية سابقة على تاريخ طلب القيد.
وفي جميع الأحوال لا يجوز التعامل على أسهم الشركة التي قيدت أسهمها قيداً مؤقتاً خلال الفترة من تاريخ القيد وحتى بدء التداول على هذه الأسهم إلا بموافقة الهيئة، ويعتبر القيد كأن لم يكن في حالة عدم قيام الشركة بطرح أسهمها خلال ستة أشهر من تاريخ القيد، ويجوز مد هذه المهلة بموافقة الهيئة في الحالات التي تقدرها بناء على المبررات والخطة الزمنية التي تقدمها الشركة.
كما يجوز قيد أسهم الشركات غير المستوفاة للشروط الواردة بالبند (5) و/أو (8) من هذه المادة في إحدى الحالات الآتية:
الأولى: تقديم الشركة طالبة القيد القوائم المالية لثلاث سنوات سابقة على طلب القيد فعلية معدة طبقاً للشروط والأحكام المشار إليها بالبند (5)، وبشرط ألا يقل متوسط صافي الأرباح السنوية المتولدة للشركة من نشاطها لغرضها المحقق لغرضها الرئيسي عن (5%) من متوسط رأس المال المدفوع منسوبة إلى آخر ثلاث سنوات لطلب القيد، وبشرط عدم تحقق صافي خسائر من نشاطها الرئيسي المحقق لغرضها خلال أي من السنوات المالية الثلاثة السابقة على طلب القيد.
الثانية: للشركات الملزمة بإعداد قوائم مالية مجمعة تقديم قوائم مالية كاملة سابقة عن سنة مالية واحدة على طلب القيد، على أن تكون معدة طبقاً للشروط والأحكام والمشار إليها بالبند (5) وبشرط ألا تقل نسبة صافي الربح قبل خصم الضرائب المتولد من ممارسة الشركة و/الشركات التابعة لنشاطها الوارد في نظمها الأساسية في آخر سنة مالية سابقة على طلب القيد على (5%) من رأس مال طلب القيد كما تظهره القوائم المالية المجمعة، وبشرط ألا تقل نسبة صافي الربح قبل الضريبة بعد حسابه على أساس سنوي بالقوائم المالية الدورية - في حالة الانتهاء من إعدادها - عن نسبة (5%) من رأس المال المرجح بالمدة.
وفيما عدا الحالتين السابقتين لا يجوز قيد أسهم الشركات غير المستوفاة للبند (8) إلا بعد توافر الشروط التالية:
أ- ألا يقل صافي حقوق المساهمين بالشركة عن ضعف الحد الأدنى لرأس المال المدفوع المشار إليه بالبند (6).
ب- أن يكون ما لا يقل عن نصف رأس المال المملوك لمساهمين لهم خبرة وسابقة أعمال متميزة في مجال نشاط الشركة أو من البنوك أو شركات التأمين.
ج- تقديم دراسة معتمدة من أحد المستشارين الماليين المقيدين بسجل الهيئة توضح فرص النمو والربحية على الأقل ما تتضمن الدراسة على الأقل ما يلي:
- ما باشرته الشركة من نشاط.
- ما أبرمته الشركة من عقود.
- خطة عمل الشركة.
- خبرات فريق الإدارة بالشركة.
- ما حصلت عليه الشركة من تراخيص وموافقات (صناعية وبيئية إلخ..).
- التوقعات المالية المستقبلية.
- مدى كفاية الموارد المالية للشركة لتحقيق خطتها.
- التوقعات المستقبلية للربحية.
- القيمة العادلة للسهم عند الطرح.
د- أية تقارير أو مستندات تطلبها البورصة وعلى الأخص تقرير مقيم عقاري مقيد من المقيدين بسجلات الهيئة عن كافة أصول الشركة.
الرابعة: مع عدم الإخلال بالقيود القانونية الخاصة بتداول الأسهم وفقاً للمادتين (45، 46) من قانون شركات المساهمة وشركات التوصية بالأسهم والمسئولية المحدودة الواحد الصادر بالقانون رقم (159) لسنة 1981 والمادة (138) من لائحته التنفيذية والمادة (53) من قانون الاستثمار الصادر برقم (72) لسنة 2017، للشركات الملزمة بإعداد مجمعة مالية خاصة بها من تاريخ تأسيسها وحتى تقديم طلب القيد على أن تكون معدة طبقاً للشروط والأحكام المشار إليها بالشرط (5) مرفقاً بها تقرير الفحص الدوري المحدود من مراقب الحسابات وكذلك آخر قوائم مالية سنوية لجميع شركات المساهمة التابعة لها السابقة على طلب القيد، على أن تكون معتمدة من الجمعية العامة العادية للشركة ومصدق عليها من الجهة الإدارية المختصة، وألا يقل إجمالي حقوق المساهمين التابعة المطلوب قيدها عن إجمالي أموال رؤوس المال المدفوعة عن آخر سنة مالية سابقة لطلب القيد لتلك الشركات الفعلية طبقاً للقوائم المالية عن آخر سنة مالية سابقة على طلب القيد، وبشرط ألا تقل نسبة صافي الربح قبل خصم الضريبة المتولد من ممارسة الشركة/الشركات التابعة المطلوب قيدها لنشاطها الوارد من غرضها الأساسية في نظمها الأساسية في آخر سنة مالية سابقة على طلب القيد عن 5% من رأس المال المدفوع كما تظهره القوائم المالية المجمعة، وبشرط ألا تقل نسبة صافي الربح قبل الضريبة بعد حسابه على أساس سنوي بالقوائم المالية الدورية - في حالة الانتهاء من إعدادها - عن نسبة 5% من رأس المال المرجح بالمدة.

الخامسة: للشركات الناتجة عن إعادة الهيكلة بالتقسيم لشركات مقيدة غير مقيدة أسهمها بالبورصة المصرية تقديم القوائم المالية الخاصة بها عن سنة مالية كاملة سابقة على طلب القيد على أن تكون معدة طبقاً للشروط والأحكام المشار إليها بالشرط (5) مرفقاً به تقرير الفحص الدوري المحدود من مراقب الحسابات وكذلك قوائم مالية سنوية أخرى للشركة القاسمة، على أن تكون جميعها معتمدة من الجمعيات العامة للشركات ومصدق عليها من الجهة الإدارية المختصة، وبشرط ألا تقل نسبة صافي الربح قبل خصم الضريبة المتولد من ممارسة الشركة لنشاطها الوارد في نظمها الأساسية في آخر سنة مالية سابقة على طلب القيد عن 5% من رأس المال المطلوب قيده كما تظهره القوائم المالية لها.

وللشركات الناتجة عن إعادة الهيكلة بالاندماج لشركات مقيدة أسهمها بالبورصة تقديم القوائم المالية الخاصة بها عن الفترة من تاريخ إتمام إجراء إعادة الهيكلة وحتى تاريخ تقديم طلب القيد معدة طبقاً للشروط والأحكام المشار إليها بالشرط (5) مرفقاً به تقرير الفحص الدوري المحدود من مراقب الحسابات وكذلك القوائم المالية السنوية عن سنتين ماليتين للشركتين المندمجتين وعلى أن تكون معتمدة من الجمعية العامة للشركات ومصدق عليها من الجهة الإدارية المختصة، وبشرط توافر شروط القيد بالشركات المندمجة قبل اعتماد القوائم المالية للسنة التي يتم فيها استيفاء الشروط الواردة بالبند (5) و/أو (8) بحسب الأحوال بهذه المادة، وذلك لمدة لا تقل عن (24) شهراً ميلادياً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد بالبورصة، وأن يتم الاحتفاظ بذات النسبة السابقة في أي زيادة لاحقة لرأس مال الشركة لذات الفترة، وذلك فيما عدا الأسهم المجانية.

وفي الحالات الخمس المشار إليها أعلاه، يجب على الأقل احتفاظ كل مساهم يمتلك نسبة لا تقل عن (10%) فأكثر من أسهم الشركة و/أو من يحل محله من باقي المساهمين بالشركة عند القيد بمساهمته في رأس مال الشركة وبما لا يقل عن (25%) من إجمالي أسهم الشركة حتى اعتماد القوائم المالية للسنة التي يتم فيها تحقيق الشروط الواردة بالبند (5) و/أو (8) بحسب الأحوال بهذه المادة، وذلك لمدة لا تقل عن (24) شهراً ميلادياً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد بالبورصة، وأن يتم الاحتفاظ بذات النسبة السابقة في أي زيادة لاحقة لرأس مال الشركة لذات الفترة، وذلك فيما عدا الأسهم المجانية.

ويجوز - بعد موافقة الهيئة والجمعية العامة العادية للشركة - أن تنتقل ملكية الأسهم المحتفظ بها - جزء منها أو بالكامل - خلال مدة الاحتفاظ المشار إليها في حال كون المشتري إليها بنك أو شركة تأمين أو صندوق استثمار مباشر أو أحد الكيانات المتخصصة في الاستثمار أو شخص اعتباري أو شخص له خبرة وسابقة أعمال متميزة في مجال نشاط الشركة، وبشرط أن يتعهد بالالتزام بشرط الاحتفاظ حتى نهاية المدة المقررة.$t9b$
