INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins8;

WITH ins9 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 1, NULL, $t10a$مادة 7 مكرر$t10a$, $t10b$يشترط لقيد أسهم الشركة ذات غرض الاستحواذ قيداً مؤقتاً بجداول البورصة ألا يقل رأس مالها المصدر والمدفوع عن عشرة ملايين جنيه مصري أو ما يعادلها بالعملات الأجنبية، وتلتزم الشركة بزيادة رأس مالها نقداً إلى مائة مليون جنيه مصري أو ما يعادلها بالعملات الاجنبية خلال ثلاثة أشهر من تاريخ قيد أسهمها بالبورصة مع مراعاة ما يلي:

1- أن يتم طرح أسهم زيادة رأس المال في اكتتاب خاص على مستثمرين مؤهلين أو مؤسسات مالية وفقاً للتعريف الوارد بقرار مجلس إدارة الهيئة رقم (177) لسنة 2024 الصادر بشأن ضوابط منح الترخيص واستمراره للشركات العاملة في الأنشطة المالية غير المصرفية، وعلى أن تتضمن مذكرة المعلومات - بحد أدنى - البيانات الآتية:
- بيانات عامة عن الشركة.
- خبرات مؤسسي الشركة ومجلس إدارتها.
- القطاعات المستهدفة والضوابط الاستثمارية المستهدفة.
- الخطة الاستثمارية للاستحواذ على الشركة أو الشركات المستهدفة.
- أسلوب الاستحواذ سواء نقداً أو بأرصدة دائنة أو بمبادلة أسهم أو باندماج.
- مخاطر الاستثمار.
- ضوابط الاسترداد.
- الإطار المنظم لإدارة رأس مال الشركة بما في ذلك الأموال المحصلة من ذلك في الاكتتاب.
- الأشخاص المرتبطة والأطراف ذوي العلاقة.
- وسائل تجنب تعارض المصالح.
- إعلام المستثمرين المؤهلين في أسهم الزيادة بأن قيولهم أسهمهم الاكتتاب يعني تداول أسهمهم بالقيمة الإسمية لحين نشر تقرير إفصاح للمادة (138) من اللائحة التنفيذية للقانون 159 لسنة 1981 عن الثلاثة الأشهر بعد تنفيذ الاستحواذ أو نشر القوائم المالية عن أول سنة مالية بعد التأسيس.
2- ألا يقل عدد المساهمين بالشركة بعد الاكتتاب عن خمسين مساهم.
3- ألا تقل نسبة حرة التداول للأسهم عن (5%) من إجمالي أسهم الشركة.
4- أن يتم الاحتفاظ بحصيلة زيادة رأس المال في الاكتتاب لدى أحد البنوك المصرية، على ألا يتم استخدامها إلا لأغراض الاستحواذ.
5- أن يكون التداول على أسهم الشركة مقصوراً على المؤسسات المالية والمستثمرين المؤهلين وتحت مسئولية شركة السمسرة المنفذة، لحين استيفاء متطلبات المادة (7 مكرراً 1) من هذه القواعد.
6- يُعرض مشروع قرار الاستحواذ متضمناً كافة التفاصيل المتعلقة بنشاط الشركة أو الشركات المستهدفة بالاستحواذ على الجمعية العامة غير العادية للشركة وذلك خلال ستة أشهر من تاريخ قيد أسهم الشركة بالبورصة، ولا يجوز للمؤسسين وأشخاصهم المرتبطة التصويت على قرار الاستحواذ، ويكون للمساهمين المعترضين على قرار الاستحواذ بانسحاب الجمعية العامة الخارج من تاريخ اجتماع الجمعية العامة خلال ثلاثين يوماً من تاريخ التصويت على هذا القرار.
7- على الشركة القيام بتنفيذ الاستحواذ خلال سنتين من تاريخ القيد بالبورصة، ويكون الاستحواذ على الشركات المستهدفة بنسبة (100%) أو أي نسبة أخرى من رأس المال أو حقوق التصويت، على أن يتبعها الإبقاء على الشركات التي تم الاستحواذ عليها أو الاندماج فيها أو تملك جزء من أسهمها كشركات قائمة وذلك وفقاً لما تقرره الجمعية العامة غير العادية للشركة في هذا الشأن.
8- على الشركة بعد تنفيذ الاستحواذ نشر تقرير الإفصاح المشار إليه بالمادة (138) من اللائحة التنفيذية للقانون رقم (159) لسنة 1981 بعد اعتماده من الهيئة موضحاً به خطة الشركة وتفاصيل عمليات الاستحواذ التي تمت وكذا وأسلوب المحافظة على استمرار القيد فيما يخص الحد الأدنى لنسبة الأسهم حرة التداول وعدد المساهمين، أو قيام الشركة بنشر القوائم المالية عن أول سنة مالية بعد التأسيس.
9- ألا تقل نسبة احتفاظ المؤسسين عند تقديم طلب القيد عن (100%) من حصتهم في الشركة وذلك حتى اعتماد القوائم المالية للسنة التي يتم فيها تحقيق شرط الربحية الوارد بالبند (8) من المادة (7) من هذه القواعد وبشرط مرور 24 شهراً ميلادياً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد بالبورصة، وأن يتم الاحتفاظ بحصتهم في أي زيادة تالية نتيجة اكتتابهم في تلك الفترة اللاحقة.

وفي جميع الأحوال، يكون التعامل على أسهم الشركة بالقيمة الاسمية خلال الفترة من تاريخ القيد وحتى نشر تقرير الإفصاح طبقاً للمادة (138) من اللائحة التنفيذية للقانون 159 لسنة 1981 أو لحين إصدار الشركة لقوائم مالية عن أول سنة مالية بعد التأسيس، ويجوز أن يتم التعامل على أسهم الشركة باسعر الاكتتاب بعد نشر تقرير الإفصاح المشار إليه في حال قيامها بزيادة رأس مالها من خلال مستثمر مالي مستقل يحددها القيمة العادلة التي يحددها بسجلات الهيئة مع مراعاة تجنيب علاوة الإصدار في حساب احتياطي خاص عقب إتمام زيادة رأس مالها ونتيجة لذلك.

ولا يجوز التعامل على أسهم الشركة ذات غرض الاستحواذ التي قيدت قيداً مؤقتاً خلال فترة الثلاثة أشهر من تاريخ قيدها وحتى استيفاء باقي الشروط الخاصة بزيادة رأس المال إلا بموافقة الهيئة، ويعتبر القيد المؤقت كأن لم يكن في حالة عدم قيام الشركة باستيفاء الشروط المشار إليها أعلاه خلال ثلاثة أشهر من تاريخ القيد، ويجوز مد هذه المهلة في الحالات التي تقدرها الهيئة بناء على المبررات والخطة الزمنية التي تقدمها الشركة.$t10b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins9;

WITH ins10 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 2, NULL, $t11a$مادة 7 مكرر 1$t11a$, $t11b$يشترط للتداول على أسهم الشركات ذات غرض الاستحواذ لكافة المتعاملين بالبورصة ما يلي:

1- تقدم الممثل القانوني للشركة بطلب للبورصة لإتاحة التداول على أسهم الشركة لكافة المتعاملين بالبورصة.
2- استيفاء الشركة للبندين (3، 2) من المادة (7) من هذه القواعد.
3- نشر نشرة طرح أو معلومات أو مذكرة إفصاح عن تداول أسهمها بالوسائل المعدة لذلك بالبورصة بعد الاعتماد من الهيئة مرفقاً بها دراسة القيمة العادلة للسهم معدة من مستشار مالي مستقل.
4- تنفيذ خطة الاستحواذ جزئياً أو كلياً تنفيذاً للبندين (7، 6) من المادة (7 مكرراً) من هذه القواعد.
5- تقديم الشركة القوائم المالية عن فترة لا تقل عن ستة أشهر تالية لتاريخ الاستحواذ على أن تكون تلك القوائم معدة وفقاً لمعايير المحاسبة المصرية مرفقاً بها تقرير مراجعة شاملة من أحد مراقبي الحسابات المقيدين بسجل الهيئة، ومصدقاً عليها من الجمعية العامة للشركة على أن يتوافر بها معياري صافي الربح وحقوق المساهمين.
6- مع عدم الإخلال بحكم البند (9) من المادة (7 مكرراً) واستثناءً من البند (7) من المادة (7) والفقرة الأخيرة من المادة (44) والفقرة الأخيرة من المادة (44 مكرراً "1")، من هذه القواعد، يجب ألا تقل نسبة احتفاظ المؤسسين في الشركة ذات غرض الاستحواذ وكذلك أعضاء مجلس الإدارة التنفيذيين والمديرين التنفيذيين المستحوذ عليها في حال اكتتابهم في زيادة رأس مال الشركة الناتجة عن الاستحواذ بالمبادلة أو بالرصيد الدائن عن (51%) من حصتهم في الشركة وذلك لمدة لا تقل عن (12) شهراً ميلادياً عن تلك الزيادة من تاريخ قيد أسهم الزيادة وصدور القوائم المالية السنوية أو الدورية التي يتوافر بها شرطي الربحية وحقوق المساهمين المنصوص عليهما بالبند (8) من المادة (7) من هذه القواعد، ويسري على كل البند هذا من هذه القواعد على أي زيادة تالية ناتجة عن الاستحواذ بالمبادلة أو بالرصيد الدائن.$t11b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins10;

WITH ins11 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t12a$مادة 8$t12a$, $t12b$مع عدم الإخلال بالقيود القانونية الخاصة بتداول الأسهم وفقاً للتشريعات المنظمة لها، يجوز قيد أسهم الشركات المصرية التي تأسست عن طريق طرح أسهمها في اكتتاب عام أو خاص إذا لم تطرحت لاحقاً بعد القيد المؤقت لأسهمها أو طرحت اكتتاب من خلال طرح عام أو خاص بناءً على نشرة اكتتاب أو مذكرة معلومات معتمدة من الهيئة والتي لم يصدر قوائم مالية عن سنتين ماليتين إذا استوفت الشروط الكاملتين الآتية:

1- ألا يقل رأس المال المصدر والمدفوع للشركة المطلوب قيد أسهمها عن مثلي الحد الأدنى المشار إليه لرأس المال بالمادة (7) بند (6).
2- ألا تقل نسبة الأسهم حرة التداول عن إجمالي أسهم الشركة، أو ما يعادل 1/8 في الألف من رأس المال السوقي حر التداول بالبورصة، وألا يقل عدد مساهمي الشركة عن 300 مساهم.
3- ألا يقل عدد الأسهم المصدرة المطلوبة قيدها عن 20 مليون سهم.
4- ألا تقل نسبة احتفاظ المساهمين الذين يمتلكون نسبة (10%) فأكثر من رأس مال الشركة و/أو من يحلون محلهم من باقي المساهمين بالشركة عند تقديم طلب القيد بأسهمهم في الشركة وبما لا يقل عن نسبة (25%) من إجمالي أسهم الشركة وذلك حتى اعتماد القوائم المالية للسنة التي يتم فيها تحقيق شرط الربحية الوارد بالبند (8) من المادة (7) من هذه القواعد، وبشرط مرور (24) شهراً ميلادياً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد بالبورصة، وأن يتم الاحتفاظ بذات النسبة في أي زيادة لرأس مال الشركة لذات الفترة وذلك فيما عدا الأسهم المجانية.
5- ألا تنشر الشركة طالبة القيد والتي لم تصدر قوائم مالية عن سنة مالية واحدة على الأقل الإفصاح المشار إليه بالمادة (138) من اللائحة التنفيذية للقانون رقم (159) لسنة 1981 قبل بدء التداول وبعد اعتماده من الهيئة، وأن يتم تضمين نشرة الطرح أو الاكتتاب أو مذكرة المعلومات المعتمدة كافة الأحوال بحسب المعلومات المبينة بالمادة (138) المشار إليها.
6- أن تقدم الشركة قبل الطرح دراسة قيمة عادلة تضمن دراسة جدوى مستقبلية معتمدة من أحد المستشارين الماليين المقيدين بسجل الهيئة وفقاً للمعايير المصرية للتقييم المالي للمنشآت، ومرفقاً بها تقرير مراقب حساباتها بشأن دراستها، على أن تتضمن الدراسة على الأقل ما يلي:
- ما باشرته الشركة من نشاط.
- ما أبرمته الشركة من عقود.
- التوقعات المالية المستقبلية.
- التوقعات المستقبلية للربحية ومدى كفاية الموارد المالية المتولدة من نشاط الشركة المالي لتحقيق هذه الأرباح.
- القيمة العادلة للسهم.

وفي جميع الأحوال، لا يجوز التعامل على أسهم الشركة خلال الفترة المؤقتة إلا بموافقة الهيئة، ويعتبر القيد المؤقت كأن لم يكن في حالة عدم قيام الشركة باستيفاء باقي الشروط بعد انتهاء المدة المحددة من هذه القواعد.$t12b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins11;

WITH ins12 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, NULL, $t13a$مادة 9$t13a$, $t13b$يشترط لقيد أسهم الشركات الصغيرة والمتوسطة ما يأتي:

1- ألا تقل نسبة الأسهم المراد طرحها عن (25%) من إجمالي الأسهم المقيدة للشركة أو ربع في الألف من رأس المال حر التداول بالبورصة، ويقصد بالطرح في تطبيق هذا الشرط عرض أسهم الشركة للبيع بالبورصة بناءً على نشرة طرح أو تقرير الإفصاح بغرض الطرح معتمد من الهيئة يتضمن ما انتهت إليه دراسة المستشار المالي المستقل بتحديد القيمة العادلة للسهم وتقرير مراقب حساباتها بشأن هذه الدراسة وفقاً لمعيار المراجعة المصرية ذات الصلة، على أن ينشر ما سبق على شاشات البورصة لمدة خمسة أيام على الأقل قبل بدء الطرح فضلاً عن تنفيذ الطرح الإلكتروني عن نشره على الموقع الإلكتروني للبورصة المصرية.
2- ألا يقل عدد المساهمين بالشركة بعد الطرح عن 100 مساهم مع مراعاة أن تكون الأسهم المخصصة موزعة في ضوء الضوابط التي تحددها البورصة بهدف التحقق من عدم صورية الطرح.
وتعتبر الشركة مستوفية للشرطين السابقين إذا كان هيكل مساهميها عند تقديم طلب القيد يتضمن 25% على الأقل تملكها من رأس مال الشركة أو ربع في الألف من رأس المال السوقي حر التداول بالبورصة لا يقل عن 10% من أسهم الشركة لمساهمين بخلاف المؤسسين والمساهمين الرئيسيين، وبها عدد مساهمين لا يقل عن 100 مساهم، وألا تكون أي من الأسهم المتضمنة في تلك النسبة مرهونة، على أن يتم نشر تقرير إفصاح قبل بدء التداول بالبند المشار إليها بالبند (1).
3- ألا تقل نسبة الأسهم حرة التداول عن (10%) من إجمالي أسهم الشركة أو 1/8 في الألف من رأس المال السوقي حر التداول بالبورصة بما لا يقل عن 5% من أسهم الشركة.
4- ألا يقل عدد الأسهم المصدرة المطلوب قيدها عن 100 ألف سهم.
5- أن تقدم الشركة طالبة القيد القوائم المالية لسنتين ماليتين سابقتين على طلب القيد، على أن تكون هذه القوائم معدة وفقاً لمعايير المحاسبة المصرية وتمت مراجعتها وفقاً لمعايير المراجعة المصرية بواسطة أحد مراقبي الحسابات المقيدين بسجل الهيئة ومصدق عليها من الجمعية العامة للشركة والمختصة الإدارية المختصة.
ويجوز للجنة القيد قبول أوراق قيد الشركة التي لم يصدر لها قوائم مالية إلا عن سنة مالية إن لم تكن كاملة في حالة تقديم الشركة خطط عمل لثلاث سنوات قادمة تحدد فيها الأرباح المتوقعة على أن تكون هذه الخطط معتمدة من أحد الخبراء المعتمدة لدى الهيئة أو الراعي.
6- أن يكون رأس المال المصدر مدفوعاً بالكامل وبحد أدنى مليون جنيه وأقل من مائة مليون جنيه وذلك من واقع آخر قوائم مالية سنوية أو أخر قوائم مالية دورية مرفقاً بها تقرير شامل من مراقب الحسابات ومصدق عليها من الجمعية العامة للشركة.

على أن تلتزم الشركة خلال ثلاثة سنوات من تاريخ القيد بزيادة وصول رأسمالها المصدر والمدفوع بالكامل تنفيذاً لما ورد بتقرير الإفصاح المشار إليه او خطط عمل الشركة المشار إليها بالبند (1).
7- ألا تقل حقوق المساهمين في آخر قوائم مالية سنوية أو دورية سابقة على تاريخ طلب القيد عن رأس المال المدفوع.
8- تقديم تعهدات بألا تقل نسبة احتفاظ المساهمين الذين يمتلكون نسبة (10%) فأكثر أو من يحلون محلهم من باقي المساهمين بالشركة عن نسبة (51%) من الأسهم المملوكة لهم في رأس مال الشركة حال توافرها وبحد أدنى ما يملكونه أقل من نسبة (25%) من إجمالي الأسهم المصدرة، يتم استكمال نسبة 25% من مساهمات أعضاء مجلس الإدارة ومؤسسي الشركة أو غيرهم من مساهمي الشركة وبشرط مرور (24) شهراً ميلادياً وصدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد بالبورصة للشركات غير المستوفاة للبند عند القيد أو من تاريخ الطرح بالنسبة للشركات غير المستوفاة للبند (25%) من أسهم الشركة لسنة مالية تالية فيما عدا الأسهم المجانية، وعلى أن تسري شروط ذات الاحتفاظ على أي زيادة تالية في رأس مال الشركة فيما عدا الأسهم المجانية.
وفي جميع الأحوال يستمر الاحتفاظ بنسبة (25%) من أسهم الشركة لسنة مالية تالية فيما عدا الأسهم المجانية، وعلى أن تسري شروط ذات الاحتفاظ على أي زيادة تالية في رأس مال الشركة فيما عدا الأسهم المجانية.
ويجوز - بعد موافقة الهيئة والجمعية العامة العادية للشركة - أن تنتقل ملكية الأسهم المحتفظ بها - جزءاً منها أو بالكامل - خلال مدة الاحتفاظ المشار إليها في حال كون المشتري إليها بنك أو شركة تأمين أو صندوق استثمار مباشر أو أحد الكيانات المتخصصة في الاستثمار أو شخص اعتباري أو شخص له خبرة وسابقة أعمال متميزة في مجال نشاط الشركة، وبشرط أن يتعهد بالالتزام بشرط الاحتفاظ حتى نهاية المدة المقررة.

ولا تسري أحكام الفقرة الثانية من هذا البند في حال تعديل قيد أسهم الشركة وفقاً للمادة (7) من هذه القواعد وتنفيذاً وفقاً للبند (1) أو (2) مكرراً (23) من هذه القواعد بشأن صدور القوائم المالية الدورية عن سنتين ماليتين من تاريخ القيد أو الطرح.

9- أن تتعاقد الشركة طالبة قيد أسهمها مع أحد الرعاة المعتمدين بالسجل المعد لذلك الغرض، ويكون الراعي مسئولاً عن معاونة الشركة في مرحلة قيد أوراقها المالية كما يتولى مسئولية متابعة التزام الشركة بقواعد ومعايير القيد والإفصاح، على أن يستمر الراعي لمدة لا تقل عن سنتين من تاريخ القيد، ويلتزم خلالها بإجراء تغطية بحثية للشركة التي يرعاها.

وفي جميع الأحوال لا يجوز التعامل على أسهم الشركة خلال هذه الفترة من تاريخ التسجيل وحتى بدء التداول على هذه الأسهم إلا بموافقة الهيئة، ويعتبر القيد المؤقت كأن لم يكن في حالة عدم قيام الشركة بطرح أسهمها خلال شهر من تاريخ تسجيلها لدى الهيئة ويجوز مد هذه المهلة بموافقة الهيئة في الحالات التي تقدرها.

وفي جميع الأحوال لا يجوز التعامل على أسهم الشركة التي قيدت قيداً مؤقتاً خلال الفترة من تاريخ القيد وحتى بدء التداول إلا بموافقة الهيئة، ويعتبر القيد كأن لم يكن في حالة عدم قيام الشركة بطرح أسهمها خلال ستة أشهر من تاريخ القيد، ويجوز مد هذه المهلة بموافقة الهيئة في الحالات التي تقدرها بناء على المبررات والخطة الزمنية التي تقدمها الشركة.$t13b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins12;

WITH ins13 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, NULL, $t14a$مادة 10$t14a$, $t14b$يشترط لاستمرار قيد أسهم الشركات بالبورصة توافر الحد الأدنى لعدد المساهمين ونسبة الأسهم حرة التداول والحد الأدنى لعدد الأسهم المطلوب قيدها والشروط العامة لقيد الأوراق المالية المنصوص عليها بالمادة (6) من هذه القواعد، وفي حال عدم توافر أي من هذه الشروط تطبق أحكام الباب السادس من هذه القواعد.

كما تلتزم الشركات التي تم قيد أسهمها طبقاً للمادة (8) بتقديم إفصاح نصف سنوي معتمد من مجلس الإدارة عن تطورات أعمالها وأنشطتها وذلك طوال مدة التزام المساهمين الرئيسيين والمؤسسين بالاحتفاظ بأسهمهم.

تلتزم الشركة التي تم قيدها بجداول البورصة المصرية بألا يزيد رأسمالها المرخص به عن خمسة أمثال رأسمالها المصدر.$t14b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins13;

WITH ins14 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, NULL, $t15a$مادة 11$t15a$, $t15b$يتم قيد الأوراق والأدوات المالية التي تصدرها الدولة بشرط تقديم نشرة الطرح أو مستندات الإصدار المعتمدة من السلطة المختصة بالجهة المصدرة.$t15b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins14;

WITH ins15 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, NULL, $t16a$مادة 12$t16a$, $t16b$يشترط لقيد السندات وصكوك التمويل توافر الشروط الآتية:

أ. أن تكون قد طرحت للاكتتاب العام أو الخاص بناء على نشرة اكتتاب أو مذكرة معلومات معتمدة أياً كان القانون الخاضع له الجهة التي أصدرتها.
ب. تقديم شهادة توضح درجة التصنيف الائتماني الممنوح للإصدار.
ج. تقديم طلب القيد مرفقاً به كافة البيانات والمستندات الآتية:
1- تعهد الجهة المصدرة بموافاة الهيئة والبورصة بشهادة تصنيف ائتماني حديثة خلال 90 يوماً من نهاية السنة المالية سنوياً تجدد للإصدار سنوياً.
2- تعهد بالإفصاح الفوري للهيئة والبورصة عن الأحداث الجوهرية وبتقديم شهادة تصنيف ائتماني جديدة خلال 15 يوماً من تاريخ الإفصاح.
3- تعهد بموافاة البورصة بمحضر اجتماع جماعة حملة السندات وما يفيد تعيين الممثل القانوني المفوض لهم ويفيد تعيين الجهة الإدارية المختصة وذلك خلال أشهر ثلاثة أقصاها من تاريخ غلق باب الاكتتاب في تلك السندات، وتعهد بموافاة الهيئة والبورصة ببيان العوائد المستحقة لحملة السندات أو الصكوك وما تم سدادها منها وذلك قبل موعد الصرف بخمسة عشر يوماً على الأقل.

وفي جميع الأحوال يجب اعتماد كافة الاوراق والمستندات المقدمة للقيد من السلطة المختصة بالشخص الاعتباري.$t16b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins15;

WITH ins16 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 1, NULL, $t17a$مادة 12 مكرر$t17a$, $t17b$يشترط لقيد واستمرار قيد السندات أو صكوك التمويل غير الحاصلة على تصنيف ائتماني، والتي يقتصر التداول عليها بين المؤسسات المالية والأشخاص ذوي الملاءة المالية وفقاً للمادة الثالثة من قرار مجلس إدارة الهيئة رقم (23) لسنة 2016 المشار إليه، توافر الشروط الآتية:

1- ألا تقل المدة المتبقية للسندات أو الصكوك المطلوب قيدها عن عام من تاريخ القيد، وعدم حدوث أي من حالات الإخلال فيما يتعلق بسداد مستحقات حملة السندات.
2- ألا تزيد قيمة السندات أو الصكوك المطلوب قيدها عن صافي أصول الشركة وفقاً لآخر قوائم مالية معتمدة من مراقب حساباتها.
3- تقديم المستندات التالية:
أ. موافقة الهيئة المسبقة على تقديم طلب القيد.
ب. مذكرة المعلومات المعتمدة من الهيئة.
ج. شهادة من مراقب حسابات الشركة بما يفيد قدرتها على سداد التزامات حملة السندات أو الصكوك في مواعيد استحقاقها من التدفقات النقدية المتوقعة للشركة.
د. تعهد من الممثل القانوني للشركة بتشكيل جماعة حملة السندات أو صكوك التمويل خلال ثلاثة أشهر من تاريخ القيد.
ه. تعهد من الممثل القانوني للشركة بالتزام الشركة بسداد كافة مستحقات حملة السندات أو الصكوك من أصل وعائد وفقاً للتواريخ المحددة بمذكرة المعلومات، وعدم الإخلال بالالتزامات المنصوص عليها في مذكرة المعلومات.
4- نشر تقرير إفصاح بغرض التداول وفقاً للنموذج الذي تعده البورصة وتعتمده الهيئة، يتضمن بالأخص ما يلي: (شروط إصدار السندات أو الصكوك - موقف ما تم استهلاكه من السندات أو الصكوك - العائد وتاريخ الصرف وأسس حسابه - المؤشرات المالية - نية الجهة في السداد المعجل - المخاطر - الضمانات الممنوحة).
5- الالتزام بالإفصاح الفوري للهيئة والبورصة عن الأحداث الجوهرية، والالتزام بكافة الإفصاحات المطلوبة والتشريعات المنظمة طوال فترة قيد السندات أو صكوك التمويل ومواعيدها الواردة بمذكرة المعلومات.
6- الالتزام بموافاة الهيئة والبورصة طوال فترة القيد ببيان العوائد المستحقة لحملة السندات أو الصكوك وما يتم سداده منها وذلك يوماً قبل الصرف بخمسة عشر يوماً على الأقل.
7- الالتزام بأن يكون من بين مهام مراقبي الحسابات المقيدين لدى الهيئة طوال الفترة المحددة لقيد السندات أو الصكوك أداء مهامه بمعايير المراجعة المصرية باشتراطات مدى التزام الشركة بإصدار السندات أو الصكوك.

وفيما عدا البندين (2، 3/ج، ه) أعلاه، تسري أحكام هذه المادة في شأن الصكوك غير الحاصلة على تصنيف ائتماني حال رغبة الجهة المصدرة في قيدها بالبورصة وذلك مع مراعاة شهادة تصنيف السداد ووكيل السداد بموقف توزيعات عائد المشروع المُمول بها الصكوك على المستثمر ومالكيها وأن يتضمن تقرير الإفصاح المشار إليه توزيع المشروع المُمول من طلب القيد.$t17b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins16;

WITH ins17 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 13, 0, NULL, $t18a$مادة 13$t18a$, $t18b$يتم قيد وثائق صناديق الاستثمار المغلقة المصرية التي يتوافر فيها الشروط الآتية:

أ. تقديم نشرة الاكتتاب العام أو مذكرة المعلومات الخاص في حالة الطرح الخاص معتمدة من الهيئة مرفقاً بها نسخة من الأصل من باقي المستندات اللازمة للموافقة على طرح وثائق الصندوق والواردة باللائحة التنفيذية للقانون 95 لسنة 1992.
ب. تقديم تعهد من مدير خدمات الإدارة وشركة الإفصاح للبورصة والهيئة بالالتزام بتقديم تقارير ربع سنوية تتضمن صافي أصول الصندوق وعدد وثائقه ونصيب كل وثيقة من صافي قيمة أصول الصندوق وبيان بأي توزيعات أرباح صرفها بخمسة عشر يوماً على الأقل. وكذلك تعهد من مجلس إدارة الصندوق بتقديم تقارير نصف سنوية عن أدائه ونتائج أعماله ومركزه المالي بالإضافة إلى الإجراءات التي يتخذها الإدارة المالي لإدارة المخاطر المرتبطة بالصندوق.
ج. تقديم تعهد من مجلس إدارة الصندوق بالإفصاح للهيئة والبورصة بشكل مسبق وفوري عن أي تصرف ينطوي على تعارض للمصالح وما يفيد موافقة المجلس المسبقة أو جماعة حملة الوثائق بحسب الأحوال على القيام بهذا التصرف.
د. تقديم تعهد من شركات خدمات الإدارة بالالتزام بموافاة البورصة بصافي قيمة الوثيقة قبل بداية جلسة التداول التالية لتاريخ احتسابها.$t18b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins17;

WITH ins18 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 14, 0, NULL, $t19a$مادة 14$t19a$, $t19b$يتم قيد الوثائق المتداولة لصناديق المؤشرات التي يتوافر فيها الشروط الآتية:

أ. تقديم نشرة الاكتتاب العام أو مذكرة المعلومات في حالة الطرح الخاص لهذا الإصدار معتمدة من الهيئة.
ب. تقديم تعهد من شركة خدمات الادارة للبورصة ببيان اليوم التالي عن صافي قيمة الوثيقة Net Asset Value وكذلك إخطار البورصة يومياً بأي تغيير في عدد الشهادات القائمة، وأي خطوات تتخذ بشأن وصفه مؤقتاً لإيقاف استرداد أو بيع أو أي خطوات تتخذ بشأن صفه مؤقتاً لإيقاف استرداد أو بيع وأي خطوات تتخذ بشأن صفه بشأن الاسترداد أو البيع، ونسبته، وأي خطوات تتخذ بشأن صفه ونسبته موعد وقيمة الكوبونات الموزعة.$t19b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins18;

WITH ins19 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 15, 0, NULL, $t20a$مادة 15$t20a$, $t20b$مع مراعاة الاتفاقيات ومذكرات التفاهم المبرمة بين كل من الهيئة العامة للرقابة المالية والبورصات أو الجهات الرقابية الأجنبية الخاضع لها السوق محل الأسهم المقيد به شهادات الإيداع المصرية والبورصات، يجوز قيد شهادات الإيداع المصرية متى توافرت فيها الشروط الآتية:

أ. ألا تقل القيمة الاسمية لإجمالي الشهادات المطلوب قيدها عن مائة مليون جنيه مصري أو ما يعادلها من العملات الأجنبية القابلة للتحويل، وألا يقل عدد حملة شهادات الإيداع المصرية عن 150 مالك شهادة بعد الطرح.
ب. ألا تقل نسبة شهادات الإيداع المصرية حرة التداول عن 5% من إجمالي التداول.
ج. أن تكون الأسهم محل شهادات الإيداع مقيدة في أحدى البورصات الأجنبية التي تخضع لإشراف جهة رقابية مماثلة اختصاصاتها الهيئة في مجال سوق المال.
د. أن تلتزم الشركة بتقديم القوائم المالية ويجب إعداد هذه القوائم طبقاً للمعايير الدولية ومراجعتها طبقاً للمعايير الدولية أو الأمريكية كما تلتزم بتقديم تقارير مجلس الإدارة بالبورصة، وأن تقدم للبورصة نسخة مترجمة باللغة العربية من هذه القوائم لنشرها على الموقع الالكتروني لها.
ه. أن تتوافر في الشركة الأجنبية المصدرة لشهادات الإيداع المطلوب قيدها نسبة الحد الادنى لصافي الربح وحقوق المساهمين اللازمة لقيد أسهم الشركات المصرية وفقا لهذه القواعد.

ويشترط لاستمرار القيد استمرار الشروط المرتبطة بالحد الأدنى لنسبة التداول حرة وعدد حملة الشهادات وإجمالي القيمة الاسمية لشهادات الإيداع.

وفي جميع الأحوال لا يجوز للشركة الأجنبية أن تقيد جزء من أوراقها بالبورصة في صورة أسهم وجزء آخر في صورة شهادات إيداع مصرية في ذات الوقت.$t20b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins19;

WITH ins20 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 16, 0, NULL, $t21a$مادة 16$t21a$, $t21b$أولاً: الأسهم الأجنبية

يشترط استيفاء الشروط الآتية لقيد أسهم الشركات الأجنبية:

أ. أن تكون أسهم الشركة مقيدة في إحدى البورصات الأجنبية التي تخضع لإشراف جهة تمارس اختصاصات مماثلة لاختصاصات الهيئة في مجال سوق المال وأن تكون الأسهم بالجنيه المصري أو بعملة أجنبية قابلة للتحويل للجنيه المصري.
ويجوز قيد أسهم هذه الشركات لو لم تكن مقيدة في بورصة أجنبية متى كانت ملكيتها لحقوق التصويت أكثر من 50% مجمعة أصولها وإيراداتها من شركات مصرية تابعة لها، وبشرط أن تقدم الشركة قوائم مالية مجمعة عن سنتين ماليتين سابقتين على طلب القيد وفق النحو الوارد بالبند (ب) من هذه المادة، على أن تلتزم بإعداد القوائم المالية لها بعد القيد وفقاً لمعايير المحاسبة المصرية وأن يتم مراجعتها وفقاً لمعايير المراجعة المصرية.
ب. أن تلتزم الشركة بتقديم تقرير مراقب الحسابات والقوائم المالية للبورصة ويجب إعداد هذه القوائم ومراجعتها وفقاً للمعايير المصرية أو الدولية أو الأمريكية كما تلتزم بتقديم تقارير مجلس الإدارة للبورصة، وأن تقدم للبورصة نسخة مترجمة باللغة العربية من هذه القوائم لنشرها على الموقع الالكتروني لها.
ج. ألا يقل رأس مال الشركة الأجنبية المطلوب قيد أسهمها عما يعادل 100 مليون دولار أمريكي وعن 10 مليون دولار أمريكي في حالة الشركة المتوسطة والصغيرة، وإذا كانت الشركة غير مقيدة في بورصة أجنبية وكانت نسبة أكثر من (50%) فأكثر من حقوق ملكيتها وأصولها وإيراداتها تابعة لشركات مصرية على النحو الوارد بالبند (أ) أولاً من هذه المادة، يكون الحد الأدنى لرأس المال المصدر والمدفوع للشركة ذات الحد الأدنى المتطلب لقيد أسهم الشركات المصرية.
د. توافر شروط ذات طرح وشهادات الإيداع المصرية بالنسبة لعدد المساهمين ونسبة الأسهم حرة التداول والحد الأدنى لعدد الأسهم المطلوب قيدها، والواردة بالمادة (15).
ه. أن يكون للشركة ممثل قانوني بمصر.

ثانياً: السندات وصكوك التمويل الأجنبية

يتم قيد السندات وصكوك التمويل المصدرة من شركات أجنبية بشرط توافر شروط قيد السندات وصكوك التمويل المصرية.

ويجوز قيد السندات والصكوك المصدرة من المؤسسات المالية الدولية والصناديق الإقليمية والدولية للتنمية ولا يشترط تشكيل جماعة لحملة هذه السندات أو صكوك التمويل.

ثالثاً: وثائق صناديق الاستثمار المغلقة الأجنبية

يتم قيد وثائق صناديق الاستثمار المغلقة الأجنبية المصدرة من صناديق الاستثمار الأجنبية بشرط توافر شروط قيد وثائق صناديق الاستثمار المغلقة المصرية.

رابعاً: وثائق صناديق المؤشرات الأجنبية

يتم قيد وثائق صناديق المؤشرات الأجنبية بذات شروط قيد وثائق صناديق المؤشرات المصرية، شريطة أن تكون وثائق الصندوق مقيدة في بورصة بلد المنشأ وأن تكون تلك البورصة خاضعة لرقابة هيئة رقابية ذات اختصاصات مماثلة لاختصاصات الهيئة في مجال سوق المال.$t21b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins20;

WITH ins21 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 17, 0, NULL, $t22a$مادة 17$t22a$, $t22b$يشترط لاستمرار قيد الأوراق المالية الأجنبية استمرار قواعد القيد ومتطلبات الإفصاح المقررة للأوراق المالية المصرية المناظرة.$t22b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
