WITH ins22 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 18, 0, NULL, $t23a$مادة 18$t23a$, $t23b$يجب على الشركة أو الجهة طالبة القيد أن ترفق بطلب القيد ما يأتي:

1. عنوان المركز الرئيسي للشركة أو الجهة وجميع الفروع المسجلة لها داخل البلاد وخارجها.
2. نسخة من نشرة الطرح أو تقرير الإفصاح بغرض الطرح - بحسب الأحوال - المقدم للهيئة والجدول الزمني لتنفيذ الطرح.
3. هيكل الملكية موضحاً به نسبة ملكية المساهمين الذين تبلغ ملكيتهم (5%) أو أكثر وذلك لكل من الشركة طالبة القيد وشركتها القابضة/ الأم والشركات التابعة والشقيقة.
4. بيان بأسماء أعضاء مجلس إدارة الشركة طالبة القيد وأوراقها المالية وما إذا كان يشغل منصب تنفيذي أو غير تنفيذي أو مستقل، وكذلك أسماء وصفات المديرين التنفيذيين الذين قد يكون في مكنتهم الاطلاع على المعلومات الداخلية للشركة طالبة القيد وشركاتها القابضة والتابعة والشقيقة أن وجدت على ألا يقل عدد المستقلين عن عضوين.
5. بيان بالداخليين والجهة طالبة القيد ورقم الكود الموحد لكل منهم يتضمن الآتي:
أ. الاسم بالكامل والجنسية ومحل الإقامة والعمل والجهة التي يمثلها في عضوية مجلس الإدارة إذا كان ممثلاً لشخص اعتباري وما إذا كان شخص اعتباري وما إذا كان يشغل وظيفة عضو مجلس إدارة إحدى الشركات المقيدة لها أوراق مالية بالبورصة وكذلك مساهمته في الشركات الأخرى التي تبلغ ملكيته فيها نسبة 5% أو أكثر من رأسمالها.
ب. نسبة المساهمة المباشرة وغير المباشرة وكذا حصة الأقارب حتى الدرجة الثانية في رأس مال الشركة ونسبة المساهمة في أي شركة تابعة أو شقيقة.
ج. بيان بما يشغله من وظائف في شركة أخرى سواء كانت مقيدة بالبورصة أو غير مقيدة والجهة التي يمثلها إذا كان عضواً في مجلس إدارة الشركة الأخرى ونسبة ملكيته وأقاربه حتى الدرجة الثانية في هذه الشركة في هذه الشركة الأخرى.
د. بيان بالقروض أياً كان نوعها، الممنوحة من كل من أعضاء مجلس الإدارة والأطراف ذات العلاقة إلى الشركة.
6. بيان بأسماء اللجان المنبثقة عن مجلس الإدارة واختصاصاتها وأسماء أعضائها وبخاصة أعضاء لجنة المراجعة.
7. بيان معتمد من المستشار القانوني للشركة بالرهونات المقررة على أصول الشركة موضحاً به البيانات الرئيسية لهذه الرهونات.
8. ملخص العقود التي تساوي أو تزيد عن (5%) من إيرادات العام المالي السابق التي تكون الشركة طالبة القيد طرفاً فيها أو أي شركة تابعة لها موضحاً فيها الالتزامات المتبادلة بين المبالغ المسددة بموجبها، وكذلك ملخص لأية عقود أو اتفاقات سارية بين الشركة طالبة القيد أو شركة تابعة أو شقيقة أو أي من المساهمين بنسبة (5%) أو أكثر أو أي من أعضاء مجلس الإدارة التنفيذيين وأي من عقود المعاوضة بما في ذلك المديرين التنفيذيين.
9. إقرار من الشركة بمطابقة جميع التعاقدات أو الاتفاقات مع مساهميها أو أعضاء مجالس إدارتها أو المديرين التنفيذيين للأحكام القانونية المقررة وللأوضاع التي تتبعها الشركة في تعاملاتها مع الغير.
10. بيان معتمد من الممثل القانوني للشركة طالبة القيد بأسماء وعناوين مسئول العلاقات مع المستثمرين ووسائل الاتصال به على أن يكون المسئول عن العلاقات مع المستثمرين من مديري الشركة الذين لهم حق الاطلاع على المعلومات والمستندات وتحدد الإجراءات التنفيذية اختصاصاته - التي تعتمدها الهيئة - وشروطه وتأهيله.
11. بيان معتمد من المستشار القانوني للشركة بالقضايا التي تؤثر على مركز الشركة المالي وتكون الشركة طالبة القيد طرفاً فيها مبيناً موقف الهيئة في كل قضية.
12. تقرير من مراقب حسابات الشركة بالموقف الضريبي للشركة وفقاً لما يقضي به قانون الضرائب.
13. تعهد الشركة طالبة القيد أسهمها أو شهادات الإيداع بتعديل نظامها الأساسي إذا كان يتضمن تخصيص مقاعد معينة لجهات أو مساهمين محددين ليتوافق مع الطرح ودخول مساهمين جدد.
14. إقرار معتمد من المستشار القانوني للشركة يفيد عدم صدور أي من أحكام ضد أي من أعضاء مجلس الإدارة خلال السنوات الخمس السابقة على تاريخ تحرير الإقرار بعقوبة جناية أو بعقوبة جنحة مخلة بالشرف أو الأمانة أو أحد الجرائم المنظمة للأنشطة المالية غير المصرفية - ما لم يكن قد رد إليه اعتباره - أو تكرار ثبوت ارتكاب أياً منهم مخالفات جسيمة لقانون سوق رأس المال خلال ثلاث سنوات ولو تم إبراؤه، وكذلك تعهد الممثل القانوني للشركة باتخاذ إجراءات الدعوة للجمعية العامة للنظر في تنحية عضو مجلس الإدارة الذي صدر ضده أي مما سبق.
15. تعهد من الشركة بالإفصاح إلى الهيئة والبورصة حال تحقق أي حالة من الحالات المنصوص عليها في البند السابق خلال الأجل الأقصر الذي تحدده الهيئة أو الأجل الأدنى الذي تتوافر فيه الشروط المقررة.
16. تعهد الممثل القانوني للشركة بالانضمام لعضوية صندوق حماية المستثمر من المخاطر غير التجارية فور القيد واستمرار عضويته به طوال فترة القيد وسداد كافة المبالغ المستحقة للصندوق في المواعيد المقررة لها.
ويجوز للهيئة أو البورصة طلب تقديم تقرير يفيد أن حسابات مراقب حسابات الشركة يفيد وجود نظام إلكتروني مالي ومحاسبي كافٍ وبيان مدى فعالية بيئة الرقابة للنظام المالي والمحاسبي.
ولا تسري البنود أرقام (2، 3، 5، 6، 8، 9، 13) من هذه المادة على طلبات قيد السندات وصكوك التمويل.$t23b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins22;

WITH ins23 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 19, 0, NULL, $t24a$مادة 19$t24a$, $t24b$يجب على الشركات الصغيرة أو المتوسطة أن ترفق بطلب القيد بالإضافة إلى (18) ما يلي:

1. تعهد موقع بين كلا من الشركة والراعي المعتمد وفقاً للنموذج المعد لذلك من البورصة المصرية، يتضمن واجبات والتزامات الشركة طالبة القيد والراعي المعتمد تجاه الهيئة والبورصة المصرية.
2. إقرار من الراعي والشركة بتقديم كافة المعلومات والبيانات المطلوبة بشأن عملية قيد أوراقها المالية في البورصة المصرية والوفاء بالالتزامات الناشئة عن القيد.
3. خطط عمل لثلاث سنوات قادمة تحدد فيها الأرباح المتوقعة على أن تكون هذه الخطط معتمدة من الراعي أو أحد المستشارين الماليين المعتمدين لدى الهيئة.$t24b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins23;

