WITH ins25 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 21, 0, NULL, $t26a$مادة 21$t26a$, $t26b$على اللجنة البت في طلب القيد خلال خمسة أيام عمل من تاريخ استيفاء المستندات والإجراءات المقررة.$t26b$
