WITH ins26 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, NULL, $t27a$مادة 22$t27a$, $t27b$للشركة أو الجهة الطالبة تقديم طلب إعادة نظر في قرار اللجنة الصادر برفض القيد أمام مجلس إدارة البورصة وذلك خلال خمسة عشر يوماً من تاريخ الإخطار بالقرار وعلى المجلس البت في القرار في أول جلسة تالية له.

وفي حالة تأييد مجلس إدارة البورصة لقرار لجنة القيد يجوز للشركة أو الجهة تقديم التماس للهيئة خلال خمسة عشر يوماً من تاريخ الإخطار بقرار مجلس إدارة البورصة.$t27b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins26;

WITH ins27 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, NULL, $t28a$مادة 23$t28a$, $t28b$تقيد الأوراق المالية بأحد جداول البورصة ويتم تداول الأوراق المالية بأسواق البورصة وفقاً لقواعد البورصة وإجراءات التداول التي تعدها البورصة وتعتمدها الهيئة.$t28b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
