WITH ins28 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 1, NULL, $t29a$مادة 23 مكرر$t29a$, $t29b$يتم تعديل قيد أسهم الشركات المقيدة وفقاً للمادة (9) من هذه القواعد لتصبح مقيدة وفقاً للمادة (7) من هذه القواعد في الحالتين الآتيتين:

1- بناءً على قرار من لجنة القيد بالبورصة عند وصول رأسمال الشركة إلى 200 مليون جنيه فأكثر، مع إلزام الشركة بتوفيق أوضاعها فيما يتعلق بعدد الأسهم المقيدة، ونسبة الأسهم حرة التداول وعدد المساهمين وفقاً لشروط قيد أسهم الشركات المنصوص عليها بالمادة (7) من هذه القواعد.
2- بناء على طلب الممثل القانوني للشركة التي يتجاوز رأسمالها المقيد أرأسمالها المصدر من 100 مليون جنيه وأقل من 200 مليون جنيه، شريطة أن يتوافر بشأنها عدد الأسهم المقيدة، ونسبة الأسهم حرة التداول وعدد المساهمين المشار إليهم بالمادة (7) من هذه القواعد.

وفي الحالتين المشار إليهما أعلاه يكون للشركة الالتزام بنشر إفصاحاتها وفقاً لقواعد الشركات الصغيرة والمتوسطة المقيدة وفقاً للمادة (9) من هذه القواعد لمدة عام ميلادي من تاريخ الموافقة على نقلها.

كما يجوز للشركات التي تم قيدها وفقاً للمادة (7) من هذه القواعد ويقل رأسمالها السابقة في القواعد وفقاً لها أو ما يقاربها في القواعد وفقاً للمادة (7) من هذه القواعد أن تقدم طلب لنقل قيد أسهمها للبورصة شريطة أن يتوافر بشأنها عدد الأسهم المقيدة، ونسبة الأسهم حرة التداول وعدد المساهمين المشار إليهم بالمادة (9) من هذه القواعد، وفي هذه الحالة يكون للشركة الالتزام بنشر إفصاحاتها وفقاً لقواعد الشركات الصغيرة والمتوسطة من تاريخ الموافقة على نقلها.$t29b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins28;

WITH ins29 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, NULL, $t30a$مادة 24$t30a$, $t30b$في حالة قيام شركة مقيدة بإعادة الهيكلة بالتقسيم ونتج عن ذلك شركة قاسمة وشركة أو أكثر منقسمة، يتم تعديل بيانات قيد أسهم الشركة القاسمة الناتجة عن إعادة الهيكلة باعتبارها امتداد للشركة المقيدة قبل القيد بعد إعادة الهيكلة بالتقسيم شرط استمرار توافر الحد الأدنى لعدد المساهمين ورأس المال وعدد الأسهم حرة التداول والإجمالي بالسجل التجاري، ويبدأ التداول على أسهم الشركة القاسمة والمنقسمة عقب نشر تقرير الإفصاح عن التقسيم من كل شركة وفقاً للمادة (138) من اللائحة التنفيذية للقانون (159) لسنة 1981، وعلى أن يتم نشر التقرير على الموقع الالكتروني الذي تخصصه الهيئة لهذا الغرض وعلى شاشات التداول وعلى الموقع الإلكتروني للبورصة، وأن يتم نشر ملخص هذا التقرير في إحدى الصحف اليومية المصرية واسعة الانتشار الصادرة باللغة العربية وذلك وفقاً للنموذج الذي تعده الهيئة لهذا الغرض.

كما يتم قيد أسهم الشركات الناتجة عن إعادة الهيكلة بالاندماج التي تعطي مقابل رأس المال في الشركة المندمجة متى كانت أسهم الشركات المندمجة مقيدة ببورصة شريطة توافر شروط ذات الشروط الواردة بالفقرة السابقة من هذه المادة.$t30b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins29;

WITH ins30 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 25, 0, NULL, $t31a$مادة 25$t31a$, $t31b$يحظر على الشركة المصرية المقيدة أوراقها المالية القيام بالقيد الثانوي لأياً من أوراقها في أية بورصة أجنبية سواء في صورتها الأصلية أو في صورة شهادات إيداع أو في أية صورة أخرى إلا بعد الحصول على ما يفيد عدم ممانعة الهيئة التي تقبلها في ضوء المبررات حفاظاً على استقرار الأسواق.$t31b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins30;

WITH ins31 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 26, 0, NULL, $t32a$مادة 26$t32a$, $t32b$تلتزم الجهات المقيد لها أوراق مالية بجداول البورصة باستيفاء طلب قيد الإصدارات الجديدة لها أو طلب تعديل بيانات الإصدارات المقيدة خلال أقصى حد أشهر ثلاثة كحد أقصى من تاريخ الواقعة المنشئة للإصدار أو التعديل.

وتحدد الإجراءات التنفيذية الصادرة عن البورصة والمعتمدة من الهيئة التاريخ المعتمد به لاحتساب المدة السابقة.

وتلتزم الشركة المقيدة أسهمها أو شهادات إيداعها المصرية بإتمام تخفيض رأس مالها المقيد بجداول البورصة خلال ثلاثة شهور من الأكثر على تاريخ صدور قرار الجمعية العامة غير العادية بالتخفيض.

وبالنسبة للتعديلات الأخرى يلزم إتمام تعديل بيانات القيد خلال الفترة الزمنية التي تحددها الاجراءات التنفيذية الصادرة عن البورصة.$t32b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins31;

WITH ins32 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 27, 0, NULL, $t33a$مادة 27$t33a$, $t33b$مع عدم الإخلال بمتطلبات الإفصاح الواردة بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية، تسري متطلبات الإفصاح الواردة بهذا الباب على جميع الجهات والشركات المقيد لها أوراق مالية بجداول البورصة.

وتتولى البورصة نشر الإفصاحات التي ترد إليها من الهيئة، والبيانات والمعلومات التي يجب على الجهات والشركات إخطار البورصة بها وفقاً لهذه القواعد، وفي جميع الأحوال يتم النشر لما سبق مع الهيئة قبل الشر إلا في الحالات التي تحددها الهيئة.

وتلتزم الشركات والجهات المقيد لها أوراق مالية بالبورصة بسرعة الاستجابة لاستفسارات الهيئة.

كما تتولى البور صة بعد قيد الشركات المدرجة بالبورصة الشركة الشركة أو الجهة لا شأنها ما ورد بتقرير الإفصاح المنصوص عليه في المادة (138) من اللائحة التنفيذية للقانون (159) لسنة 1981، مع إخطار الهيئة بأي حال وجود انحرافات جوهرية تستلزم اتخاذ ما يلزم وفقاً للأحكام والقواعد.

وتلتزم الشركة المقيدة أسهمها بالبورصة متى بلغت إيراداتها السنوية اثنين مليار جنيه أو أكثر بموافاة البورصة بإفصاحات الشركة وفقاً للضوابط المنصوص عليها بهذه القواعد باللغتين العربية والإنجليزية.$t33b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins32;

WITH ins33 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 28, 0, NULL, $t34a$مادة 28$t34a$, $t34b$تلتزم الجهات والشركات المقيد لها أوراق مالية بالبورصة طوال فترة القيد بما يلي:

1. إخطار البورصة فوراً وقبل بدء جلسة التداول التالية على أية تعديلات تطرأ على الافصاحات المرفقة بطلب القيد بطلب القيد أو أي تغيير في البيانات سالفة الذكر، أو في البيانات الواردة بغرض الطرح أو نشرة الإفصاح الواردة بغرض الطرح مع مراعاة أحكام قانون سوق رأس المال ولائحته التنفيذية فيما يتعلق بحظر التلاعب في الأسعار وحظر استغلال المعلومات الداخلية.
2. إخطار البورصة فور صدور أحكام قضائية أو أحكام تحكيم قضائية في أي مرحلة من مراحل التقاضي بتلك الأحكام التي يكون لها تأثير على أسعار التداول أو على القرار الاستثماري للمتعاملين، وذلك بمراعاة أن يكون الإخطار فيما يتعلق بالأحكام الصادرة بأداء مبالغ مالية معينة أو ردها للمبالغ التي تتجاوز قيمتها 2% من حقوق الملكية لجهة وفقاً لآخر قوائم مالية معتمدة (سنوية أو ربع مالية).
3. إخطار البورصة بالإفصاحات أو المعلومات والبيانات قبل نشرها أو الإعلان عنها وعلى إفصاحها فور نشرها وورودها على مسئولية الجهة المرسلة وفقاً لما يتم النشر للإجراءات المعمول بها بالبورصة.
4. إخطار البورصة فور صدور أحكام قضائية بعقوبة سالبة للحرية ضد أحد أعضاء مجلس إدارة الجهة المصدرة أو أحد المسئولين الرئيسيين بها.

ويحظر على الجهة الإدلاء بأية بيانات أو معلومات تؤثر على أوضاعها أو على مركزها المالي أو على صفة خاصة للمحللين الماليين أو المؤسسات المالية أو أي أطراف أخرى قبل يتم الإفصاح عنها للجمهور وفقا لأحكام الإفصاح الواردة بهذه القواعد، وذلك ما لم تكن هذه المعلومات والبيانات مرتبطة بمسائل جوهرية ما زالت في مرحلة التفاوض شريطة توقيع اتفاقية سرية ضمان سرية المعلومات مع هذه الجهة والالتزام بأحكام المادة (43) من هذه القواعد.

كما يحظر على الجهة أن تقوم بالإفصاح عن بيانات أو معلومات لا تتفق وحقيقة وأوضاع الجهة وفي جميع الأحوال يجب أن يكون الإفصاح الذي تنشره الجهة كاملاً ومدعماً بالبيانات والمستندات وأن توافي بها عند طلبها.$t34b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins33;

WITH ins34 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 29, 0, NULL, $t35a$مادة 29$t35a$, $t35b$مع عدم الإخلال بحكم المادة (8) من القانون (95) لسنة 1992 والباب الثاني عشر من لائحته التنفيذية على كل مساهم للبورصة عند تجاوز أو انخفاض ما يملكه من الأوراق المالية الممثلة لرأس مال الشركة المقيدة بالبورصة أو حقوق التصويت بها، بما في ذلك الأسهم التي تم اكتتابه فيها عن طريق شراء حقوق الاكتتاب المقابلة لأسهم الشركة، والأطراف المرتبطة به بشكل مباشر من الأسهم وشهادات الإيداع الأجنبية المقابلة لأسهم الشركة وكذا ما يملكونه بشكل غير مباشر من خلال تملك نسبة (25%) أو أكثر من رأس مال شركة أو جهة تتملك بدورها نسبة في رأسمال الشركة المقيدة التي يساهم فيها هذا المساهم.

كما يلتزم المساهمون المشار إليهم بالفقرة السابقة بالإفصاح عن الخطة الاستثمارية المستقبلية وتوجهات المساهم بشأن إدارة الشركة إذا بلغت النسبة المشتراة منه والأطراف المرتبطة نسبة 25% أو أكثر من رأس مال أو حقوق التصويت فيها.

ويتم الإفصاح عقب التنفيذ وقبل بداية أول جلسة تداول تالية وفقاً للنموذج الذي تعده البورصة وتعتمده الهيئة لهذا الغرض. وفي جميع الأحوال تلتزم البورصة بنشر هذه البيانات فوراً وإبلاغها ويتم النشر من خلال شاشات التداول.

وعلى موقع البورصة الإلكتروني. وتسري أحكام الفقرات السابقة على أعضاء مجلس إدارة الشركة المقيدة والعاملين والأطراف المرتبطة بهم عند اكتمال أحدهم أو مضاعفاتها بنسبة 3% أو أكثر من الأوراق المالية للشركة (بما فيها حقوق الاكتتاب) على أن يشمل الإفصاح فيما يتعلق بأعضاء مجلس الإدارة ما يملكه العضو وأطرافه المرتبطة بشكل مباشر من الأسهم وشهادات الإيداع الأجنبية المقابلة لأسهم الشركة وكذا ما يملكونه بشكل غير مباشر من خلال تملك نسبة (25%) أو أكثر من رأس مال أو جهة تتملك بدورها نسبة في رأسمال الشركة المقيدة فيها يساهم فيها عضو مجلس الإدارة.

ولا يُعتبر في حكم المخالفة الحالات التي تتجاوز فيها النسب المشار إليها سابقاً في المشار إليه في المشار إليه في المشار إليها 1% من أسهم رأس المال عند التعامل من خلال أطراف مرتبطة لا تكون بالضرورة مطلعة على تعاملات بقية الأطراف في تداولاتها، وكذلك تعاملات ناتج عن قيام محافظ الأوراق المالية إدارة محافظ استثمارية لصالح أحد الأطراف المرتبطة من قبل الشركات المرخص لها.

وفي جميع الأحوال يجب على الأشخاص المخاطبين بحكم الفقرتين الأولى والرابعة من هذه المادة الإفصاح دورياً في أول يناير ويوليو عما يملكه كل منهم وأطرافهم المرتبطة بشكل مباشر أو غير مباشر وفقاً لأحكام الفقرتين المشار إليهما.$t35b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins34;

WITH ins35 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 30, 0, NULL, $t36a$مادة 30$t36a$, $t36b$تلتزم كل شركة مقيد لها أسهم أو شهادات إيداع مصرية بإخطار البورصة والهيئة دورياً بتقرير إفصاح يوضح هيكل المساهمين وعددهم وهيكل مجلس الإدارة وموقف أسهم الخزينة والتغيرات التي طرأت عليها بصورة ربع سنوية على النموذج المعتمد من الهيئة خلال 10 أيام من نهاية كل فترة.

وتلتزم البورصة بنشر تقارير الإفصاح المشار إليها بالفقرة السابقة على شاشات التداول بالبورصة فور ورودها وكذلك على الموقع الالكتروني.

كما تلتزم الشركات المقيدة أسهمها بالبورصة بالإفصاح بشكل سنوي ربع سنوي عن مدى الالتزام بأوجه استخدامات الزيادة النقدية لرأسمالها المصدر، والإجراءات التي تم اتخاذها في هذا الشأن، على أن يرفق بالإفصاح السنوي تقرير من مستشار مالي مستقل أو من مراقب الحسابات صادر عن مدى مطابقة الاستخدام الفعلي لأوجه الاستخدام التي تم الإفصاح عنها، ويتم نشر تقرير الإفصاح المتضمن ذلك وفقاً لحكم الفقرة السابقة.

وعلى الشركة إخطار البورصة فور حدوث أية تعديلات على البيانات الواردة بتقرير القيد المرافقة لطلب القيد أو الواردة بتقرير مجلس الإدارة السنوي حسب الأحوال أو أية إجراءات تتخذها الجهات الادارية قبل الشركة إذا كان ذلك يؤثر على أوضاعها ومركزها المالي وعلى الأخص:

أ. أي تعديلات في النظام الأساسي.
ب. تغيير مراقب حسابات الشركة خلال الفترة المالية.
ج. أي تغيير في رئاسة مجلس الإدارة أو أعضاء المجلس أو مدة المجلس أو المديرين الرئيسيين.
د. تغيير عنوان الشركة المسجل أو أرقام التليفونات الخاصة بها.
ه. هيكل رأس المال موضحاً به المساهمات التي تعادل أو تزيد عن (5%) من رأس المال.
و. بيان بمساهمات الشركة التي تعادل أو تزيد عن (10%) في رؤوس أموال شركات أخرى المستثمر بها أموالها.$t36b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins35;

WITH ins36 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 30, 1, NULL, $t37a$مادة 30 مكرر$t37a$, $t37b$تلتزم الشركات المقيدة بموافاة الهيئة بتقرير إفصاح في نهاية السنة المالية للشركة يوضح مدى تحقيق الشركة للنتائج الواردة بتقرير المستشار المالي المستقل أو خطة العمل المعتمدة من الراعي بالنسبة للشركات الصغيرة والمتوسطة، على أن يتضمن التقرير بيان الأسباب والمبررات وحال وجود انحرافات جوهرية عما ورد بهذا التقرير أو خطة العمل المشار إليهما.$t37b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins36;

WITH ins37 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 31, 0, NULL, $t38a$مادة 31$t38a$, $t38b$تلتزم الشركة المقيد لها أوراق مالية بموافاة البورصة بقرارات الجمعية العامة العادية وغير العادية فور انتهائها وبحد أقصى قبل بداية أول جلسة تداول تالية لانتهاء الاجتماع، كما تلتزم الشركة بموافاة البورصة بمحاضر الجمعية العامة خلال أسبوع على الأكثر من تاريخ انعقاد الجمعية العامة بالمحاضر معتمدة من قبل رئيس مجلس الإدارة.

على أن تلتزم الشركة بموافاة البورصة بمحاضر اجتماعات الجمعية العامة المصدق عليها من الجهة الإدارية المختصة خلال مدة لا تتجاوز ثلاثة أيام عمل من تاريخ تسلمها.

وتلتزم البورصة بنشر القرارات والمحاضر السابق الإشارة إليها فور ورودها على شاشات التداول وعلى الموقع الإلكتروني للبورصة.$t38b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins37;

WITH ins38 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 32, 0, NULL, $t39a$مادة 32$t39a$, $t39b$تلتزم الشركة المقيدة أوراقها المالية بموافاة البورصة والهيئة بملخص لأية قرارات صادرة عن مجلس الإدارة تتضمن أحداثاً جوهرية فور انتهاء إدارتها وبحد أقصى قبل بدء جلسة تداول تالية لانتهاء الاجتماع.

كما تلتزم الشركة المقيدة بموافاة الهيئة والبورصة ببيان نتائج أعمال إدارة الشركة بأهم نتائج أعمالها معتمد من مجلس إدارتها مقارنة بالفترة المقابلة لذلك، وفقاً للنموذج المعد لذلك من البورصة وذلك فور الموافقة من مجلس الإدارة على القوائم المالية السنوية أو الربع سنوية (الدورية)، تمهيداً لإحالتها لمراقب الحسابات ليصدر تقريره بشأنها.

وتلتزم البورصة بنشر ملخص القرارات ونتائج الأعمال المشار إليها فور ورودها وعلى شاشات التداول وعلى الموقع الإلكتروني للبورصة.$t39b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins38;

WITH ins39 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 33, 0, NULL, $t40a$مادة 33$t40a$, $t40b$تلتزم الشركة مصدرة الأسهم بالإعلان عن قرار السلطة المختصة بالتوزيعات النقدية أو توزيعات الأسهم المجانية أو كليهما، على أن يتم مراعاة ما يلي:

أ. إخطار البورصة بقرار التوزيع فوراً وقبل أول جلسة تداول تالية لانعقاد الجمعية العامة.
ب. إخطار البورصة بتاريخ التوزيعات قبل خمسة عشر يوماً على الأقل من التاريخ المحدد للتوزيع على أن يتم الإعلان عن ذلك في جريدتين يوميتين صباحيتين واسعتي الانتشار على أن يكون أحدهما على الأقل باللغة العربية.
ج. يستحق المساهم حصته في توزيعات الأرباح النقدية أو الأسهم المجانية العامة بمجرد صدور قرار الجمعية العامة بتوزيعها، وفي حال تداول أي من الأسهم خلال الفترة الزمنية من صدور قرار الجمعية العامة للشركة بتوزيع الأرباح النقدية أو الأسهم المجانية وحتى نهاية اليوم السابق للتاريخ المحدد للصرف يجب أن تنتقل كافة الحقوق المشار إليها إلى مالك الأسهم الجديد.

ويقتصر نشر القرارات والاعلانات السابقة بالنسبة للشركات الصغيرة والمتوسطة على شاشات التداول بالبورصة وكذلك على موقعها الإلكتروني لمدة لا تقل عن ثلاثة أيام عمل.$t40b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins39;

WITH ins40 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 34, 0, NULL, $t41a$مادة 34$t41a$, $t41b$تلتزم كل شركة تواجه أحداثاً يترتب عليها معلومات جوهرية وفقاً للتعريف الوارد بالبند (ب) من المادة (319) من اللائحة التنفيذية لقانون سوق رأس المال رقم (95) لسنة 1992 أن تفصح عن ذلك فوراً بإخطار البورصة لنشرها على شاشات التداول وعلى الموقع الإلكتروني للبورصة.

على أن يتم الإفصاح في موعد يسمح للبورصة بنشر هذه الأحداث فوراً أو قبل أول جلسة تداول تالية لوقت وقوع تلك الأحداث.

وتعتبر من الأحداث الجوهرية على الأخص ما يلي:

أ. أي إصدار جديد مقترح للسندات وأي ضمانات تتعلق بها.
ب. أي قرار يترتب عليه استدعاء أو إلغاء أوراق مالية سبق تسجيلها.
ج. أي تغيير مقترح في هيكل التمويل وهيكل رأس المال يتجاوز 5% من حقوق المساهمين وفق آخر قوائم مالية دورية أو الأوضاع المالية للشركة وكذا أي قيود تفرض على حجم الاقتراض المتاح للشركة.
د. أي تعاقدات بقيمة تزيد عن 5% من إيرادات آخر سنة مالية.
ه. التوزيعات النقدية أو توزيعات الأسهم المجانية أو كليهما.
و. القرارات المتعلقة بتعديل القيمة الاسمية لأسهم الشركة.
ز. أي اتفاق مقترح عليه ترتب دخول مستثمرين استراتيجيين لشراء حصة من أسهم الشركة.
ح. إقامة دعاوى قضائية أو تحكيم ضد الشركة تتعلق بنشاطها أو بإحدى مساهماتها أو بغيرها من الأصول المملوكة لها تتجاوز قيمتها (2%) من حقوق الملكية للشركة وفقاً لآخر قوائم مالية معتمدة للشركة (سنوية أو ربع سنوية).
ط. صدور أية قرارات من الجهات الإدارية بالدولة تؤثر على أنشطة الشركة وأي تعديل أو سحب أو إلغاء لهذه القرارات.
ي. أي تعاملات تجارية مع أطراف ذات العلاقة.
ك. إقامة دعاوى قضائية ضد أحد أعضاء إدارة الشركة أو أحد المديرين الرئيسيين بما يتعلق بشأنه المرتبط بمخالفات منسوبة لأي منهم.
ل. أي تغيير جوهري يطرأ على سياسة توزيعات الأرباح خلال العام المالي، مع بيان مبررات هذا التغيير وأثره على المساهمين.

ويجب على الشركة أن تلتزم في أخطارها بذل عناية الرجل الحريص للتأكد من أن أي بيانات أو وقائع أو معلومات تقوم بإبلاغها تكون صحيحة وغير مضللة وأنها لا تستبعد أو تخفي أي شيء من شأنه أن يكون مضمون هذه البيانات أو الوقائع أو المعلومات.$t41b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins40;

WITH ins41 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 34, 1, NULL, $t42a$مادة 34 مكرر$t42a$, $t42b$مع عدم الإخلال بحكم المادة (21) من قانون سوق رأس المال وبقواعد الإفصاح الواجب الالتزام بها وفقاً للقانون واللائحة التنفيذية له وما ورد بهذه القواعد، يجوز للهيئة أن تطلب من الشركة المقيد لها أسهم بالبورصة دراسة الشركة للقيمة العادلة لسهم الشركة وذلك في حال وجود تغير سعري في اتجاه واحد بنسبة أكبر من 50% خلال مدة زمنية لا تتجاوز ثلاثة أشهر أو بنسبة أكبر من 75% خلال مدة زمنية لا تتجاوز ستة أشهر بما لا يتناسب مع اتجاه مؤشرات السوق و/أو القطاع الذي تنتمي إليه الشركة المصدرة و/أو نتائج أعمال الشركة ومدى وجود أخبار جوهرية تبرر ذلك التغير.

وعلى الشركة تكليف أحد المستشارين الماليين المقيدين بسجلات الهيئة بإعداد الدراسة وملخص لها على أن يتم إرسالها للهيئة خلال مدة لا تتجاوز شهراً من تاريخ طلب الهيئة، ويتم نشر ملخص الدراسة على شاشات التداول وعلى الموقع الالكتروني للبورصة، وكذا نشره بالصفحة الرئيسية للموقع الالكتروني للشركة المصدرة.$t42b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins41;

WITH ins42 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 35, 0, NULL, $t43a$مادة 35$t43a$, $t43b$تلتزم كل شركة مقيد لها أوراق مالية بجداول البورصة بإخطار الهيئة بالقوائم المالية السنوية وتقرير مراقب الحسابات إليها قبل شهر من التاريخ المحدد لانعقاد الجمعية العامة للشركة، وللهيئة فحص الوثائق المشار إليها وتبلغ الشركة بملاحظاتها حال وجودها، وتطلب إعادة النظر في الوثائق المشار إليها بما يتفق ونتائج الفحص، فإذا لم تستجب لذلك تلتزم الشركة عند نشر القوائم المالية وتقرير مراقب الحسابات بأن يرفق بهما ملاحظات الهيئة والتعديلات التي طلبتها وتتحمل الشركة نفقات النشر التي طلبتها إليها.

ومع مراعاة أحكام القانون (159) لسنة 1981 والقانون رقم (95) لسنة 1992، تلتزم كل شركة مقيد لها أوراق مالية بجداول البورصة بنشر ملخص وافٍ لتقرير إدارتها، ونشر كامل القوائم المالية السنوية والإيضاحات المتممة لها وتقرير مراقب الحسابات بشأنها وملاحظاتها بشأنها (إن وجدت) على شاشات البورصة المصرية وموقع الشركة الالكتروني وذلك قبل موعد انعقاد الجمعية العامة بواحد وعشرين يوماً على الأقل على أن يبقى النشر قائماً حتى نشر القوائم المالية السنوية التالية، ويجب أن يشمل هذا النشر المستقلة والمجمعة للشركات الملزمة بتقديم قوائم مالية مجمعة، فإذا أجرت الجمعية العامة أي تعديلات على تلك القوائم تلتزم الشركة بنشر بيان تلك التعديلات خلال أسبوع من تاريخ اعتماد الجمعية العامة للقوائم المالية المعدلة وفي جميع الأحوال لا يجوز الدعوة لانعقاد الجمعية العامة للتصديق على القوائم قبل تسليمها مستوفاة للهيئة ولإدارة البورصة.

وتلتزم الشركات بنشر ملخص للقوائم المالية السنوية والإيضاحات المتممة لها وتقرير مراقب الحسابات وملاحظاته بشأنها، في إحدى الصحف المصرية اليومية واسعة الانتشار الصادرة باللغة العربية وذلك وفقاً للنموذج الذي تعده الهيئة لهذا الغرض.

كما تلتزم الشركات بنشر القوائم المالية الدورية والتقارير المرتبطة بها والمشار إليها أعلاه بما في ذلك القوائم المالية الدورية التي اتخذت أساساً لإجراء توزيعات دورية، على شاشات التداول بالبورصة والموقع الالكتروني للشركة على أن يبقى النشر قائماً حتى نشر القوائم المالية الدورية التالية.

تلتزم الشركات المقيدة الراغبة في إعادة تقييم الأصول الثابتة بغرض عرض تأثيرها على قوائمها المالية بمراعاة أن يتم إعادة تقييم الأصول الثابتة من خلال أحد المقيمين المعتمدين لدى الهيئة، ذلك مسبقاً وفقاً لمعايير المحاسبة المصرية نفاذاً بمعايير المحاسبة الصادرة عن الهيئة عن معايير التقييم الصادرة عن الهيئة، ومتضمناً تقرير مراقب الحسابات على القوائم المالية بعد التأثير قدر الإمكان على أقرب جمعية عامة لاعتماد القوائم المالية بعد التأثير.$t43b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins42;

WITH ins43 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 36, 0, NULL, $t44a$مادة 36$t44a$, $t44b$مع عدم الإخلال بحكم المادة (6) من القانون (95) لسنة 1992، تقوم البورصة المصرية بنشر ملخص واف بنشر القوائم المالية الدورية والسنوية للشركات الصغيرة والمتوسطة وكذلك الإيضاحات المتممة لها وتقارير الحسابات وملاحظاتها عليها (إن وجدت) وكافة تقارير الإفصاح المشار إليها في قواعد القيد الالكتروني على الموقع الالكتروني للبورصة في اليوم التالي لتسليمها لثلاثة أيام عمل على الأقل.$t44b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins43;

WITH ins44 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 37, 0, NULL, $t45a$مادة 37$t45a$, $t45b$مع مراعاة أحكام المادة (82) من قانون البنك المركزي والجهاز المصرفي والنقد الصادر بالقانون رقم (88) لسنة 2003 والمادتين (27، 28) من لائحته التنفيذية، يلتزم مجلس إدارة الشركة المقيد لها أسهم أو شهادات إيداع مصرية بجداول البورصة بتشكيل لجنة للمراجعة من عدد فردي لا يقل عن ثلاثة من الأعضاء من بين أعضاء مجلس الإدارة غير التنفيذيين، ويجوز أن تضم اللجنة في عضويتها أعضاء من خارج الشركة، ويجب أن يكون غالبية أعضاء اللجنة من الأعضاء المستقلين على أن يكون رئيس اللجنة من بينهم، وفي جميع الأحوال، يجب أن يكون أعضاء اللجنة المشهود لهم بينهم بالكفاءة والخبرة في مجال العمل المالي وأن يكون على الأقل منهم لديه خبرة بالشئون المالية والمحاسبية، كما يجوز للجنة أن تستعين بمراقب الحسابات أو من ترى مناسباً لحضور اجتماعاتها من غير أعضائها.

وتختص اللجنة بما يلي:

أ- يكون عضو منهم على الأقل لديه خبرة بالشئون المالية والمحاسبية، كما يجوز للجنة أن تستعين بمراقبي الحسابات أو من ترى مناسباً لحضور اجتماعاتها من غير أعضائها. فحص ومراجعة إجراءات الرقابة الداخلية للشركة ومدى الالتزام بتطبيقها.
ب- دراسة السياسات المحاسبية المتبعة والتغيرات الناتجة عن تطبيق معايير محاسبية جديدة.
ج- فحص ومراجعة آليات وأدوات المراجعة الداخلية وإجراءاتها وخططها ونتائجها ودراسة تقارير المراجعة الداخلية ومتابعة تنفيذ توصياتها.
د- فحص الإجراءات التي تتبع في إعداد ومراجعة القوائم المالية الدورية والسنوية.
- نشرات الاكتتاب والطرح العام والخاص للأوراق المالية.
- الموازنات التقديرية ومن بينها قوائم التدفقات النقدية وقوائم الدخل التقديرية.
ه- فحص مشروع القوائم المالية المبدئية قبل عرضها على مجلس الإدارة تمهيداً لإرسالها إلى مراقب الحسابات.
و- اقتراح تعيين مراقبي الحسابات وتحديد أتعابهم والنظر في الأمور المتعلقة باستقلاليتهم وبما لا يخالف أحكام القانون.
ز- إبداء الرأي في شأن الإذن بتكليف مراقبي الحسابات بأداء خدمات أخرى لصالح الشركة بخلاف مراجعة القوائم المالية وفي شأن الأتعاب المقدرة عنها وبما لا يخل بمقتضيات استقلالهم.
ح- دراسة تقرير مراقب الحسابات بشأن القوائم المالية ومناقشته فيما ورد به من ملاحظات وتحفظات ومتابعة ما تم في شأنها والعمل على حل الخلافات في وجهات النظر بين إدارة الشركة ومراقب الحسابات.
ط- التأكد من رفع تقرير الإدارة لمجلس الإدارة عن الخبراء المتخصصين غير المرتبطين عن طبيعة العمليات والصفقات التي تم إبرامها مع الأطراف ذات العلاقة عن مدى الإخلال بها وعن إضرارها بمصالح الشركة أو المساهمين فيها.

وعلى اللجنة التحقق من استجابة إدارة الشركة لتوصيات مراقبي الحسابات والهيئة.

وتقدم اللجنة تقارير ربع سنوية على الأقل إلى مجلس إدارة الشركة مباشرة. ولمجلس إدارة الشركة تكليف اللجنة بأية أعمال يراها في صالح الشركة خلال اختصاصها. وعلى مجلس إدارة الشركة والمسئولين عنها الرد على توصيات اللجنة خلال خمسة عشر يوماً من تاريخ الإخطار بها. وعلى رئيس اللجنة إخطار إدارة البورصة والهيئة في حال عدم الاستجابة خلال ستين يوماً للملاحظات الجوهرية التي يقدمها المجلس.

وتعفى الشركات الصغيرة والمتوسطة التي يقل مالها المصدر والمدفوع عن مائة مليون جنيه من وجود لجنة للمراجعة بها.$t45b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins44;

WITH ins45 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 37, 1, NULL, $t46a$مادة 37 مكرر$t46a$, $t46b$يلتزم مجلس إدارة الشركة المقيد لها أسهم أو شهادات إيداع مصرية بجداول البورصة بتشكيل لجنة للترشيحات والمكافآت من عدد فردي لا يقل عن ثلاثة من الأعضاء من بين أعضاء مجلس الإدارة غير التنفيذيين، على أن يكون رئيس اللجنة من الأعضاء المستقلين، ويجوز أن تضم اللجنة في عضويتها أعضاء من خارج الشركة من ذوي الخبرة، مع مراعاة تجنب تعارض المصالح.

تعقد اللجنة اجتماعاتها بصورة دورية، وتتخذ توصياتها بأغلبية أصوات أعضائها الحاضرين، وتلتزم بإعداد محاضر موثقة لأعمالها وتقارير موصياتها إلى مجلس الإدارة لاعتمادها. وتختص اللجنة بحد أدنى بما يلي:

1- فحص ودراسة طلبات الترشح لعضوية مجلس الإدارة، وبوجه خاص بالنسبة للمرشحين المستقلين، للتحقق من عدم وجود تعارض مصالح، والتأكد من توافر شروط الاستقلال والملاءمة والنزاهة والكفاءة (Fit & Proper)، وذلك وفقاً لمنهجية ومعايير مكتوبة تضعها اللجنة ويعتمدها مجلس إدارة الشركة، على أن تصدر اللجنة توصياتها بشأن كل مرشح وترفعها إلى مجلس إدارة الشركة للنظر فيها، تمهيداً للعرض على الجمعية العامة لاتخاذ ما تراه مناسباً بشأنها.
2- إبداء الرأي بشأن مدى كفاية عدد أعضاء مجلس الإدارة في اللجان المنبثقة عن المجلس، ومدى احتياجات الشركة من الخبرات، ورفع توصياتها إلى مجلس الإدارة بترشيح الأشخاص التي تراه اللجنة مناسباً لعضوية مجلس الإدارة أو عضوية لجانه أو تعيين القائمين على الإدارة التنفيذية العليا من القائمين على الإدارة التنفيذية العليا.
3- إعداد سياسات واضحة بشأن المكافآت السنوية والبدلات والاستحقاقات الخاصة بأعضاء مجلس الإدارة وأعضاء اللجان والإدارة التنفيذية العليا، وفقاً لمعايير أداء محددة، على أن يتم مراجعة تلك السياسات بصفة دورية، ويجوز الاستعانة بجهات مستقلة، وعرضها على الجمعية العامة لاتخاذ ما تراه مناسباً بشأنها.
4- مراجعة خطط التعاقب الوظيفي والبرامج التدريبية لأعضاء مجلس الإدارة والإدارة التنفيذية العليا، والإشراف على تنفيذها ومتابعة كفاءة تطبيقها بما يضمن استمرارية الأداء وفعاليته.
5- وضع سياسة اختيار الإدارة التنفيذية العليا للشركة بما يضمن استمرارية ملاءمة الأشخاص المرشحين وتناسب الوظائف الشاغرة بما يتوافق مع احتياجات الشركة والتشريعات الصادرة في هذا الشأن، على أن يتم تحديثها بشكل دوري من مجلس الإدارة واعتمادها.$t46b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins45;

WITH ins46 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 38, 0, NULL, $t47a$مادة 38$t47a$, $t47b$مع عدم الإخلال بأحكام قانون سوق رأس المال ولائحته التنفيذية، يُحظر على كل من الداخليين والمسئولين التنفيذيين بالشركة ومساهميها المالكين الرئيسيين لنسبة (20%) أو أكثر في رأس مال الشركة أو من خلال أشخاص مرتبطة، سواء بمفردهم أو من خلال أشخاص مرتبطة، التعامل على الأوراق المالية و/أو الأدوات المالية المصدرة للشركة المقيدة وذلك خلال الأيام الخمسة السابقة ليوم العمل التالي لنشر نتائج أعمالها وكذا قوائمها المالية السنوية والدورية وحال وجود اختلاف جوهري عما سبق نشره بشأنها ينطلق بنفتق ذلك على أعمال الشركة، على أن تلتزم الشركة بما يلي:

1- إعداد سجل بالأشخاص المشار إليهم بالفقرة السابقة، على أن يتضمن بحد أدنى أسماءهم وصفاتهم وممثليهم وأزواجهم وأولادهم، والرقم القومي أو رقم جواز السفر لكل منهم بحسب الأحوال (إن وجدت)، وتلتزم الشركة بتحديث السجل بصفة دورية وفور حدوث أي تغيير يطرأ عليه، كما تلتزم بإدراج صورة منه وأي تحديث يطرأ عليه لدى النظام المعد لذلك بالبورصة.
2- إخطار الأشخاص المشار إليهم بالفقرة السابقة بفترات الحظر وذلك قبل بدء فترة الحظر بوقت كاف، لتمكينهم من مراعاة تلك الفترة عند الرغبة في التعامل على الأوراق و/أو الأدوات المالية للشركة، على أن يتم الإخطار من خلال وسيلة مؤمنة قابلة للإثبات والتوثيق كالبريد الإلكتروني أو أي وسيلة مماثلة تعتمدها البورصة، وتلتزم الشركة بإدراج صور من تلك الإخطارات في ذات التوقيت لإرسالها للأشخاص المشار إليهم إليهم.

وعلى البورصة نشر البيانات الخاصة بالتعاملات المشار إليها في هذه المادة وفقاً لتنفيذ يتم بعد الجلسة عقب التنفيذ التي تم خلالها وقبل بداية الجلسة التالية من الشركة من البيانات المحدثة الواردة لذلك.

وفي جميع الأحوال، لا تسري فترات الحظر المشار إليها في هذه المادة على عمليات البيع الجبري وعمليات البيع الجبري التي تتم لاستيفاء المديونيات المرهونة بالأوراق المالية المرهونة التي تتم لصالح محافظ الأوراق المالية وصناديق الاستثمار التي تدار بواسطة مديرين مستقلين، وكذلك حالات التعامل على أسهم الخزينة أو أسهم الإثابة والتحفيز من خلال السوق المفتوح أو الصفقات الخاصة.

* تم تعديل المادة (38) بموجب قرار مجلس إدارة الهيئة رقم (148) بتاريخ 2024/7/17، ثم تم استبدالها بموجب قرار مجلس إدارة الهيئة رقم 26 بتاريخ 2026/1/22، ثم تم استبدالها بموجب قرار مجلس إدارة الهيئة رقم 195 بتاريخ 2026/8/19 (النص الحالي أعلاه هو النص الساري وفقاً لقرار 195/2026).$t47b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins46;

WITH ins47 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 39, 0, NULL, $t48a$مادة 39$t48a$, $t48b$يلتزم الداخليين والمؤسسين والمساهمين الرئيسيين والمجموعات المرتبطة بهم ألا يكونوا طرفاً في أي من عقود المعاوضة إلا بعد موافقة الجمعية العامة على أن يعرض هذا التصرف على الجمعية العامة بكافة تفاصيله وبياناته مقدماً بما في ذلك السعر والكمية قبل إجراء التصرف وذلك دون أن يحق للطرف المعني بعقد المعاوضة التصويت في الجمعية العامة.

ويستثنى من ذلك الأعمال التي تتم بطريقة المناقصات العامة إذا كان الطرف ذو المصلحة صاحب العرض الأفضل، على انه في جميع الأحوال يستبعد الداخلي صاحب المصلحة من التصويت على هذه القرارات في مجلس الإدارة، وذلك كله مع عدم الإخلال بأحكام المواد أرقام (97)، (98)، (99)، (100) من القانون 159 لسنة 1981.$t48b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins47;

WITH ins48 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 39, 1, NULL, $t49a$مادة 39 مكرر$t49a$, $t49b$بمراعاة أحكام المادة (39) من هذه القواعد وأحكام القانون رقم 159 لسنة 1981، يجوز للهيئة في الحالات التي يُعرض فيها موضوعات في اجتماعات مجلس إدارة الشركة أو جمعيتها العامة تتصل بمصلحة مباشرة أو غير مباشرة للداخليين أو المسئولين بالشركة أو مساهميها المالكين الرئيسيين لنسبة (20%) فأكثر في رأس مال الشركة سواء بمفردهم أو من خلال أطراف مرتبطة، أو من شأنها تحقيق منفعة أو ميزة تفضيلية لهم أو إعفائهم من التزام أو مسئولية أو أي شكل آخر من أشكال تعارض المصالح بينهم وبين مصلحة الشركة أو مساهميها، أن تقصر حضور المداولات والتصويت على القرارات المتخذة في الموضوعات محل الذكر على مساهمي الشركة الآخرين بخلاف المشار إليهم، كما يسري الحكم المذكور ضد الأشخاص المشار إليهم بهذه المادة حال وجود مخالفات ضدهم تتعلق بأموال الشركة بشأنها تحقيقات يجري بشأنها تحقيقات تتعلق بجرائم تتعلق بأموال الشركة.$t49b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins48;

WITH ins49 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 39, 2, NULL, $t50a$مادة 39 مكرر 1$t50a$, $t50b$يلتزم الأشخاص المشار إليهم بالمادة السابقة بالإفصاح كتابة إلى مجلس إدارة الشركة عن أي من الموضوعات محل الحالات المذكورة، وذلك فور علم صاحب الشأن بقيام تلك المصلحة وقبل بدء المداولات أو التصويت، على أن يتم إثبات ذلك بمحضر اجتماع مجلس الإدارة أو الجمعية العامة بحسب الأحوال، مع بيان اسم صاحب المصلحة وطبيعة الشأن والإجراءات المتخذة لعدم مشاركته في المداولات أو تصويته على القرارات المشار إليها.$t50b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins49;

WITH ins50 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 40, 0, NULL, $t51a$مادة 40$t51a$, $t51b$تلتزم الشركة في إعداد تقرير مجلس إدارتها المعد للعرض على الجمعية العامة بالبيانات الواردة بالملحق رقم (1) المرفق باللائحة التنفيذية للقانون 159 لسنة 1981 وذلك بالإضافة إلى البيانات التي تطلبها البورصة في نموذج تعده وتعتمده الهيئة.

وعلى أن يتضمن التقرير كذلك:

أ. عدد مرات انعقاد اجتماعات مجلس الإدارة.
ب. عدد مرات انعقاد لجنة المراجعة وما يفيد عرض تقاريرها على مجلس إدارة الشركة.
ج. متوسط عدد العاملين بالشركة خلال السنة ومتوسط دخل العامل خلال نفس الفترة.
د. في حال تطبيق الشركة لنظام إثابة وتحفيز العاملين والمديرين من خلال تملك أسهم: يتم عرض إجمالي أسهم المتاحة الممنوحة وفق النظام واجمالي ما تم منحه خلال العام واجمالي المستفيدين وعدد المستفيدين منها منذ بدء العمل بالنظام وأسماء وصفات كل من حصل على أكثر من 5% أو أكثر من إجمالي الأسهم المتاحة (أو 1% من رأسمال الشركة وفقاً للنظام المطبق بالشركة).
ه. ما اتخذ من إجراءات ضد الشركة أو أعضاء مجلس إدارتها أو مديريها من قبل الهيئة أو البورصة ولائحته التنفيذية والتي تتعلق بمخالفات لقانون سوق المال ولائحته التنفيذية.
و. كافة عقود المعاوضة التي أبرمتها الشركة مع أحد مؤسسيها أو المساهمين الرئيسيين أو المجموعات المرتبطة بهم خلال العام السابق وقيمة كل عقد وشروطه وتفاصيله وتاريخ موافقة الجمعية العامة المسبقة لكل عقد من هذه العقود.
ز. ما يفيد التزام الشركة بما تضمنته المادة (66) من القانون 159 لسنة 1981 والمادة (220) من لائحته التنفيذية، وذلك بإعداد كشف تفصيلي يتضمن على الأخص كافة المبالغ التي حصل عليها رئيس مجلس إدارة الشركة وكل عضو من أعضاء مجلس الإدارة بما فيها المرتبات والمكافآت وكافة المزايا المادية والعينية الأخرى أياً كانت صورتها، وغيرها من الالتزامات المحددة بالمادة (220) من اللائحة التنفيذية، على أن يكون هذا الكشف متاح تحت تصرف المساهمين لاطلاعهم عليه بمقر الجمعية العامة الخاص باطلاعهم على تصرف المساهمين لاطلاعهم عليه بمقر الشركة قبل انعقاد الجمعية العامة التي تدعى للنظر فيه بثلاثة أيام على الأقل قبل مقر الشركة وبمقر الانعقاد.
ح. كما يجب أن يتضمن تقرير مجلس الإدارة المعد للعرض على الجمعية العامة ما يفيد التزام الداخليين بما فيهم أعضاء مجلس الإدارة والمساهمين الرئيسيين ومديري الشركة والمجموعات المرتبطة بهم، بالإفصاح لمجلس إدارة الشركة عن كافة المعلومات والبيانات بشأن وجود حالة تعارض مصالح مع الشركة بما في ذلك ما يكون لهم من مصلحة مباشرة أو غير مباشرة في الأعمال والعقود التي تتم لحساب الشركة وكذا الإفصاح عن أية مصالح مادية أو أمور تعاملات يكون من شأنها التأثير على نشاط الشركة ومصالحها في نوع هذه الأعمال والتعاملات وقيمتها وكميتها والنفع المادي المتوقع تحقيقها منها، مع عدم اشتراك الطرف المعني الذي تتعلق حالة تعارض المصالح به في التصويت على القرار، ولا يجوز للأشخاص المذكورين بهذا البند دون موافقة مسبقة من الجمعية العامة للشركة، الاشتراك أو المساهمة في عمل من شأنه منافسة الشركة المتاجرة في أحد الأنشطة التي تزاولها وذلك دون أن يحق لهم التصويت في الجمعية العامة على هذا القرار.
ط. تقريراً وافياً بسياسة توزيعات الأرباح التي تتبعها الشركة، موضحاً الأسس والمعايير المالية والتشغيلية التي يستند إليها مجلس الإدارة في تحديد مقترحات التوزيع، مع بيان مبررات احتجاز الأرباح كلياً أو جزئياً، وخطط استخدام الأرباح المحتجزة، وأثر ذلك على المركز المالي للشركة وحقوق المساهمين.

ويجب أن يتضمن ملخص تقرير مجلس الإدارة الإفصاح بهذا البند وارداً بهذا كاملاً، على أن يتم نشر الملخص على شاشات البورصة المصرية وموقع الشركة الالكتروني.

كما يعد مجلس إدارة الشركة سنوياً تقريراً عن مدى تطبيق قواعد الحوكمة الصادر بها الدليل الاسترشادي الصادر بقرار مجلس إدارة الهيئة رقم (84) لسنة 2016 وذلك للعرض على الجمعية العامة ملحقاً به تقرير مراقب حسابات الشركة ملحقاً بشأنه وفقاً لمعايير المراجعة المصرية، على أن يتم عرضهما مرفقين بتقرير مجلس الإدارة المشار إليه أعلاه، وذلك وفقاً للنموذج الذي تعده الهيئة لهذا الغرض.$t51b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins50;

WITH ins51 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 41, 0, NULL, $t52a$مادة 41$t52a$, $t52b$لا يجوز انعقاد اجتماعات الجمعيات العامة العادية وغير العادية أثناء جلسة التداول، وللمساهم الذي يرغب في تقديم استفسارات إلى الجمعية العامة أن يتقدم بها كتابةً إلى مركز إدارة الشركة عن طريق البريد المسجل أو بالتسليم باليد مقابل إيصال استلام أو عن طريق البريد الإلكتروني للشركة مرفقاً بها صورة ضوئية من إثبات الشخصية لمالك السهم وما يفيد تجميد الأسهم لدى أمين الحفظ، وذلك كله قبل انعقاد اجتماع الجمعية العامة بثلاثة أيام على الأقل.

ولا يجوز لمجلس إدارة الشركة المخاطبة بعرض الشراء إبطاء دعوة انعقاد الجمعيات العادية أو غير العادية من تاريخ نشر قرار الهيئة باعتماد مشروع عرض الشراء وحتى تاريخ إعلان نتيجة عرض الشراء.

وتلتزم الشركة بطلب بيان من شركة الإيداع والقيد المركزي للأوراق المالية بالمساهمين الذين قاموا بتجميد أسهمهم لغرض حضور اجتماع الجمعية العامة موضحاً به هيكل المساهمين وعددهم والتغيرات التي طرأت عليها بصورة يوما من نهاية كل فترة على النموذج المعتمد من الهيئة والهيئة والحفظ التي تلتزم بمطابقة بيانات الحاضرين والتأكد من صحتها. كما تلتزم شركة الإيداع والقيد المركزي للأوراق المالية بموافاة الهيئة والاستثمار والمناطق الحرة بنسخة من البيان المسلم للشركة، وذلك فور تسليمه لها.

وفي الحالات التي تكون فيها أسهم الشركة المصرية مقيدة قيداً مزدوجاً في البورصة المصرية وأحد البورصات الأجنبية، فعلى شركة الإيداع والقيد المركزي للأوراق المالية والقيد المركزي للأوراق المالية شركاطة رقابية إشراف عليها - وشركة مقاصة الأجنبية - بناء على طلب الشركة موافاتها التزاماً بمقتضاها موافاتها ببيانات بأسماء المساهمين الذين قاموا بتجميد أسهمهم لحضور اجتماع الجمعية العامة وعدد الأسهم المجمدة لكل منهم، على أن يرفق هذا البيان المشار إليه بالفقرة السابقة.$t52b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins51;

WITH ins52 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 42, 0, NULL, $t53a$مادة 42$t53a$, $t53b$تلتزم الشركة بالتقدم بكافة المستندات اللازمة للتصديق عليها لدى الجهة الإدارية المختصة لمحاضر اجتماعاتها خلال خمس أيام عمل على الأكثر من تاريخ الاجتماع.

كما يجب على الشركة موافاة الهيئة والبورصة بأية إجراءات تالية تتخذها لدى الجهات الادارية المختصة لتنفيذ قرارات السلطة المختصة بها.

كما تلتزم الشركة بموافاة البورصة بمحاضر مجلس الإدارة المصدق عليها وذلك بحد أقصى يومي عمل من تاريخ التصديق عليها وذلك للحفظ بملف الشركة لدى البورصة على أن يتم الإفصاح عن أية تعديلات جوهرية في البيانات أو المعلومات السابق الافصاح عنها عند نشره. وإذا رأت الشركة تعذر إرسال محضر مجلس الإدارة الموثق لاحتوائه على بيانات سرية تخل بمبدأ المنافسة، يجوز لها بدلاً من إرسال المحضر أن تقدم للبورصة ملخص للقرارات التي تم التصديق عليها مرفقاً بها إقرار من الممثل القانوني للشركة بأن هذا الملخص يتضمن كافة المعلومات الجوهرية التي يجب الإفصاح عنها وفقاً لأحكام قانون سوق المال ولائحته التنفيذية والقواعد والقرارات الصادرة تنفيذاً لهما.$t53b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins52;

WITH ins53 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 43, 0, NULL, $t54a$مادة 43$t54a$, $t54b$يكون للشركة في المسائل التي مازالت في مرحلة المفاوضات أن تثبت ذلك كتابة مع تحديد الأشخاص الذين لديهم معلومات عن هذه المفاوضات فإذا اعتقدت الشركة أن هناك تسربا للمعلومات المتعلقة بهذه المفاوضات كان على الشركة إخطار البورصة فوراً لإعلام شئونها.

ويجب على ذوي الشأن الذين تصلهم المعلومات المشار إليها في مرحلة سرية عدم التعامل على الأوراق المالية لتلك الشركة أثناء تلك الفترة إلى أن تصبح تلك المعلومات متاحة للعامة.

وعلى الشركة إخطار البورصة بأية بيانات تطلبها في هذا الشأن خاصة فيما يتعلق بأسماء ذوي الشأن الذين تم اطلاعهم على المعلومات المشار إليها.$t54b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins53;

WITH ins54 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 43, 1, NULL, $t55a$مادة 43 مكرر$t55a$, $t55b$مع عدم الإخلال بأحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال، وأحكام القانون (159) لسنة 1981 ولائحته التنفيذية، وباستثناء حالات التصرف عن طريق المزاد العلني، تلتزم الشركات المقيدة بالبورصة والراغبة في التصرف من خلال إحدى شركاتها التابعة أو من إحدى الشركات التابعة الخاضعة لسيطرتها الفعلية في التصرف بالبيع في أي من العقارات أو الأصول الأخرى طويلة الأجل سواء كانت أصولاً ملموسة أو غير ملموسة أو في الأسهم المملوكة لها بشكل مباشر أو غير مباشر في شركات أخرى مقيدة أو غير مقيدة بالبورصة المصرية وسعر السهم بيع السهم يزيد أو يقل عن (10%) من سعر إغلاق السهم بالبورصة المصرية بجلسة التداول السابقة على اجتماع مجلس إدارة الشركة المتضمن الموافقة على التصرف، وكانت قيمة التصرف تمثل نسبة (10%) أو أكثر من حقوق ملكيتها -منفردة أو مجمعة بحسب الأحوال- من واقع آخر قوائم مالية سنوية أو دورية لها- بتقديم دراسة للبورصة بالسعر العادل للأصول أو الأسهم محل البيع معدة بواسطة مستشار مالي مستقل قبل اعتماد التصرف من مقيم عقاري أو مقيم الآلات والمعدات مستقل حسب طبيعة الأصل محل التصرف وفقاً للأحوال المقيدين بسجلات الهيئة، ومرفقاً بها تقرير من مراقب حسابات الشركة الراغبة بالتصرف عن تلك الدراسة، وكذلك محضر مجلس إدارتها باعتماد هذه الدراسة، وتقوم البورصة بنشر ملخص هذه الدراسة على موقعها الالكتروني وشاشات الإعلانات.

ويجب على الشركة الحصول على الموافقة المسبقة من جمعيتها العامة العادية في حال رغبتها في التنازل عن حقها في زيادة رؤوس أموال الشركات التي تساهم فيها بما يوازي بنسبة تسبب في تقليل حقوقها من حقوق ملكيتها أو واقع آخر قوائم مالية أو من إيراداتها عن سنة مالية أخرى.

وفي جميع الأحوال، لا يجوز للشركة التصرف في أكثر من (50%) من أصولها الثابتة وغيرها من الأصول الثابتة والمرتبطة بممارسة نشاطها لأنشطة الشركة إلا بموافقة الجمعية العامة غير العادية.$t55b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins54;

WITH ins55 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 44, 0, NULL, $t56a$مادة 44$t56a$, $t56b$مع عدم الإخلال بأحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال والقانون (159) لسنة 1981، وباستثناء حالات الاستحواذ عن طريق المزاد العلني، تلتزم الشركة المقيد لها أوراق مالية والراغبة في الاستحواذ من خلال إحدى الشركات التابعة لها الخاضعة لسيطرتها الفعلية على شراء أسهم شركة غير مقيدة بالبورصة المصرية أو عقارات أو الأصول الأخرى طويلة الأجل سواء كانت أصولاً ملموسة أو غير ملموسة والتي تمثل قيمتها نسبة (10%) أو أكثر من حقوق ملكية الشركة المقيد لها أوراق مالية -منفردة أو مجمعة بحسب الأحوال- من واقع آخر قوائم مالية سنوية أو دورية لها- بتقديم دراسة للبورصة بالسعر العادل للأصول محل الشراء معدة بواسطة مستشار مالي مستقل مقيد بسجلات الهيئة، أو مقيم عقاري أو مقيم الآلات والمعدات مستقل حسب طبيعة الأصل محل الشراء وفقاً للأحوال المقيدين بسجلات الهيئة، ومرفقاً بها تقرير من مراقب حسابات الشركة الراغبة في الاستحواذ عن تلك الدراسة وكذلك محضر مجلس إدارتها باعتماد هذه الدراسة، وتقوم البورصة بنشر ملخص هذه الدراسة على موقعها الالكتروني وشاشات الإعلانات.

وبمراعاة الضوابط السابقة المشار إليها، للشركة المقيد لها أوراق مالية بالبورصة، بعد الحصول على موافقة مسبقة من جمعيتها العامة غير العادية، أن تستحوذ على أسهم شركات غير مقيدة تساوي قيمتها غير مقيدة قيمة تساوي أو تزيد على (100%) من القيمة السوقية للشركة المقيد لها أوراق مالية في تاريخ اتخاذ إجراءات الاستحواذ وفقاً للنموذج الذي تعتمده الهيئة.

ويجب على الشركة قيد أوراق مالية لها بعد الحصول على موافقة مسبقة من جمعيتها العامة غير العادية على أن تستحوذ الأسهم شركة أو أصول شركة استحوذت عليها متى تجاوزت قيمة الشراء (150%) من حصتها في الشركة عن طريق الاستحواذ بالمبادلة أو بالرصيد الدائن وذلك خلال (12) شهراً ميلادياً عن تلك الزيادة وذلك يتوافر شرطي حقوق المساهمين والربحية السنوية أو الدورية المنصوص عليها بالبند (8) من المادة (7) من هذه القواعد، ويسرى هذا البند على كل زيادة تالية ناتجة من الاستحواذ بالمبادلة أو بالرصيد الدائن.$t56b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins55;

WITH ins56 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 44, 1, NULL, $t57a$مادة 44 مكرر$t57a$, $t57b$مع عدم الإخلال بأحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال، لا يجوز لشركتين خاضعتين للسيطرة الفعلية لنفس الأشخاص الطبيعية أو الاعتبارية -من بينهما شركة مقيد لها أسهم بجداول البورصة أن تمتلك أسهم أو شهادات إيداع دولية (GDR) بصورة متبادلة بين الشركتين بما يجاوز (10%) من أسهم كل منهما.

ويقصد بالسيطرة الفعلية في تطبيق أحكام هذه المادة تملك 50% فأكثر من أسهم وحقوق التصويت للشركات الخاضعة للسيطرة.

ولا يسري هذا الحكم على المساهمات القائمة وقت العمل بهذا القرار شريطة ألا يتم زيادة نسبة الملكية عما هو قائم.$t57b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins56;

WITH ins57 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 44, 2, NULL, $t58a$مادة 44 مكرر 1$t58a$, $t58b$مع عدم الاخلال بأحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال، والمادة (48) من هذه القواعد، تلتزم الشركات المقيد لها أوراق مالية بالبورصة المصرية، في حال رغبتها بالاندماج مع شركة أو أكثر مقيدة أو غير مقيدة تجاوز أو أكثر من صافي أصولها (100%) من القيمة السوقية للشركة المقيدة بالبورصة، اتخاذ إجراءات الحصول على تقرير النهائي لتقدير أصول وخصوم الشركات محل الاندماج والحصول على موافقة الجمعية العامة غير العادية على الاندماج.

وتلتزم الشركات المقيد لها أوراق مالية بالبورصة بنشر تقرير إفصاح قبل بدء التداول على أسهم الزيادة الناتجة عن الاندماج وفقاً للنموذج المعد لذلك وبعد اعتماده من الهيئة يرفق به تقرير مستقل بالقيمة العادلة لأسهم الشركة المقيد لها أوراق مالية بعد الاندماج وتقرير مراقب الحسابات عنه، مع مراعاة أنه إذا ترتب على الاندماج زيادة رأس مال الشركة المقيد لها أوراق مالية وفقد الشركة المقيدة أياً من شروط استمرار القيد أكثر أو أكثر من هذه القواعد فيجب عليها استيفاء تلك الشروط خلال ستة أشهر من تاريخ الانتهاء من إجراءات الاندماج وقيد أسهم الزيادة.

ويجب ألا تقل نسبة احتفاظ المساهمين المكتتبين في أسهم الزيادة الناتجة في رأس مال الشركة الناتجة عن الاندماج عن (51%) من حصتهم في تلك الزيادة وذلك لمدة لا تقل عن (12) شهراً ميلادياً من تاريخ قيد أسهم الزيادة وصدور القوائم المالية السنوية أو الدورية التي يتوافر بها شرطي الربحية وحقوق المساهمين المنصوص عليهم بالبند (8) من المادة (7) من هذه القواعد.

وعلى ألا تسري أحكام هذه المادة في حال كانت الشركات المندمجة المملوكة بالكامل بشكل مباشر أو غير مباشر للشركة المقيدة الدامجة.$t58b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins57;

WITH ins58 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 45, 0, NULL, $t59a$مادة 45$t59a$, $t59b$يتم إعداد القوائم المالية وفقاً لمعايير المحاسبة المصرية ونماذج القوائم المالية الواردة بتلك المعايير كما يتم مراجعتها وفقاً لمعايير المراجعة المصرية ويجب الإشارة إلى ذلك صراحة في تقرير مراقب الحسابات.$t59b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins58;

WITH ins59 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 46, 0, NULL, $t60a$مادة 46$t60a$, $t60b$على الشركة موافاة الهيئة والبورصة بما يلي:

1- نسخة من القوائم المالية السنوية الصادرة من مجلس إدارة الشركة مرفقاً بها تقرير مجلس الإدارة وتقرير مراقب الحسابات على أن يكون ذلك قبل بداية جلسة التداول للتاريخ المدون بتقرير مراقب الحسابات.

ويتم إعداد القوائم المالية السنوية واعتمادها من الجمعية العامة للشركة خلال مدة لا تتجاوز ثلاثة أشهر من تاريخ انتهاء السنة المالية للشركة ويرفق بالقوائم المالية السنوية تقرير مجلس الإدارة السنوي المشار إليه بالمادة (40)، وفي حالة تعديل الجمعية العامة للقوائم المالية توافي الهيئة والبورصة قبل بداية جلسة التداول التالية لانتهاء اجتماع الجمعية العامة ببيان معتمد عن التعديلات وأثرها على التعديلات المعتمدة من مجلس الإدارة ثم توافي الهيئة والبورصة بصورة من القوائم المعدلة بعد إعداد القوائم المعدلة خلال عشرة أيام عمل من تاريخ اعتماد الجمعية العامة للقوائم المالية التي عدلت القوائم المالية عن مراقب الحسابات المعدلة.

2- نسخة من القوائم المالية ربع السنوية (الدورية) الصادرة من مجلس إدارة الشركة مرفقاً بها تقرير الفحص المحدود على أن يكون ذلك قبل بداية جلسة التداول التالية للتاريخ المدون بتقرير مراقب الحسابات.

ويتم إعداد القوائم المالية ربع السنوية خلال خمسة وأربعين يوماً على الأكثر من تاريخ انتهاء الفترة المالية.

على أن تتضمن الإيضاحات المتممة للقوائم المالية السنوية الإفصاح عن إجمالي ما تقاضاه مراقب حسابات الشركة من مقابل مراجعة القوائم المالية السنوية أو مقابل أية أعمال إضافية أخرى خلال السنة المالية المنقضية.$t60b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins59;

WITH ins60 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 47, 0, NULL, $t61a$مادة 47$t61a$, $t61b$على الشركات الملزمة بإعداد قوائم مالية مجمعة موافاة الهيئة والبورصة بقوائمها المالية السنوية المستقلة والمجمعة مرفقاً بها تقرير الإدارة ومراقب الحسابات إليها في ذات المواعيد المشار إليها بالمادة (46) من هذه القواعد، وكذلك موافاة الهيئة والبورصة بقوائمها المالية الربع سنوية (الدورية) المجمعة مرفقاً بها تقرير مراقب الحسابات خلال ستين يوماً على الأكثر من تاريخ الأكثر على الأكثر من تاريخ نهاية الفترة المذكورة.$t61b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins60;

WITH ins61 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 47, 1, NULL, $t62a$مادة 47 مكرر$t62a$, $t62b$مع عدم الإخلال بأحكام قواعد النظم المنظمة لانعقاد الجمعيات العامة للشركات والمنصوص عليها بالقانون (159) لسنة 1981، تلتزم الشركة المقيد لها أوراق مالية أو أدوات مالية بالبورصة بإتاحة استخدام الأنظمة الالكترونية التي تكفل لمساهميها حضور اجتماعات الجمعية العامة وإثبات إجراءاتها والتصويت عليها عن بعد، بالإضافة إلى عقد الاجتماع الفعلي في المكان والتوقيت المحددين لها بدعوة الجمعية، وذلك وفقاً للضوابط التي يصدرها مجلس إدارة الهيئة.$t62b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins61;

WITH ins62 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 48, 0, NULL, $t63a$مادة 48$t63a$, $t63b$مع مراعاة حكم المادة (17) من اللائحة التنفيذية لقانون سوق رأس المال، في حالة رغبة الشركة المقيد لها أسهم أو شهادات إيداع مصرية بالبورصة المصرية في إجراءات زيادة أو تخفيض رأسمالها المرخص به و/أو تعديل غرض الشركة، أو تعديل القيمة الاسمية، يتعين اتباع الإجراءات الآتية:

1- التقدم للهيئة بطلب الحصول على موافقتها على إجراءات التعديل مرفقاً به تقرير إفصاح بغرض السير في إجراءات التعديل المقترح والمستندات المؤيدة لذلك وعلى الأخص تقرير الإفصاح المقترح للتعديل بغرض الإفصاح على النموذج المعد لذلك من الهيئة ودراسة الجدوى أو دراسة استخدام أوجه الزيادة والعوائد المتوقعة منها ومبرر موافقة مجلس إدارة الشركة على اعتماد تقرير الإفصاح المشار إليه، وذلك خلال يومي عمل من تاريخ انعقاد المجلس.
2- تقوم البورصة بنشر تقرير الإفصاح بغرض التعديل على شاشات الإعلانات بالبورصة فور تحقق الهيئة من كفاية الإفصاح واستيفاء المستندات المؤيدة لتقرير الإفصاح. ولا يتم السير في إجراءات دعوة الجمعية العامة العادية أو غير العادية للنظر في التعديل إلا بعد نشر هذا التقرير.
3- الدعوة لاجتماع الجمعية العامة العادية أو غير العادية بالشركة بحسب الأحوال للموافقة على زيادة أو تخفيض رأس المال أو تعديل غرض الشركة خلال أسبوع من تاريخ نشر تقرير الإفصاح على شاشات الاعلانات بالبورصة.
4- قيام الشركة بعرض دراسة الجدوى التفصيلية أو دراسة استخدام أوجه الزيادة والعوائد المتوقعة منها على المساهمين بالجمعية.
5- قيام الشركة بنشر تقرير إفصاح معدل في حال قيام الجمعية العامة بتعديل مقترح مجلس إدارة الشركة.
6- إذا كان التعديل يتعلق بالزيادة النقدية لرأس مال لقدامى المساهمين، فيلتزم مجلس إدارة الشركة بالإفصاح لقدامى المساهمين قبل فتح باب الاكتتاب بخمسة أيام عمل على الأقل عن القيمة العادلة المعدة من مستشار مالي مستقل في الحالتين التاليتين:
أ- إذا كانت الشركة قد حققت خسائر مرحلة خلال فترة حق وفقاً لآخر قوائم مالية معتمدة تساوى أو تجاوز (50%) من حقوق الملكية.
ب- إذا كانت نسبة الزيادة تساوي أو تجاوز رأس المال المصدر وفقاً لحقوق الملكية وفقاً لآخر قوائم مالية معتمدة.

وتلتزم الشركة التي تم قيد زيادة رأس مالها النقدية بتضمين تقرير مجلس الإدارة المعروض على الجمعية العامة للشركة بنهاية كل سنة مالية بتفاصيل حصيلة استخدام زيادة رأس المال ومدى توافقها مع الاستخدام المفصح عنه بتقرير الإفصاح المشار إليه بالبند (1).$t63b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins62;

WITH ins63 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 48, 1, NULL, $t64a$مادة 48 مكرر$t64a$, $t64b$يجوز لمجلس إدارة الشركة المقيد لها أسهم بالبورصة زيادة رأس مالها المصدر نقداً عن طريق برنامج إصدار على شرائح بناء على تفويض يصدر من الجمعية العامة غير العادية بالضوابط الآتية:

1- إعداد دراسة من مجلس إدارة الشركة بمبررات الزيادة على شرائح وأوجه استخدام الزيادة والعوائد المتوقعة منها مرفقاً بها البرنامج الزمني المقترح لزيادة رأس المال على العرض على الجمعية العامة غير العادية.
2- صدور قرار الجمعية العامة غير العادية بتفويض مجلس الإدارة في الزيادة على شرائح مثل أقصى للمال بحيث يعرض على أول اجتماع تالٍ لكل شريحة على أن يتم اتخاذ كافة الإجراءات التنفيذية اللازمة لإتمام الزيادة من شريحة لكل شريحة من البرنامج المقررة.
3- ألا يتضمن التفويض الممنوح لمجلس الإدارة التنازل عن إعمال حق الأولوية لقدامى المساهمين في الاكتتاب في الزيادة إذا كان بالسهم مقيد أو دخول مستثمرين جدد، ولا يتم تمويل زيادة رأس المال في أي شريحة من شرائح البرنامج من الأرصدة الدائنة للأر الأرباح المستحقة للمساهمين ما لم يوافق على ذلك جميع مساهمي الشركة.
4- ألا تُخص الزيادة تلك للاكتتاب لأصول مملوكة للشركة بلا أعضاء مجلس إدارتها أو المجموعات المرتبطة بهم ما لم يكن هناك موافقة مسبقة من الجمعية العامة على عقود المعاوضة المقررة للقواعد في هذا الشأن.
5- إتمام تنفيذ شرائح زيادة رأس المال خلال ثلاث سنوات من تاريخ صدور تفويض مجلس إدارة الشركة، وفي جميع الأحوال يجب الحصول على تفويض جديد من الجمعية العامة حال رغبتها في تنفيذ برنامج جديد أو في حال انتهاء مدة الثلاث سنوات المشار إليها دون تنفيذ كافة شرائح الزيادة.
6- الالتزام بألا تقل المدة المحددة للاكتتاب في كل شريحة من البرنامج عن ثلاثين يوماً من تاريخ فتح باب الاكتتاب.
7- يمتنع مجلس إدارة الشركة المستهدفة عرض شراء استخدام تفويض الجمعية العامة غير العادية بزيادة رأس المال بغرض مقاومة عرض الشراء المعتمد من الهيئة في الفترة من تاريخ صدور قرار الهيئة باعتماد مشروع عرض الشراء ومذكرة المعلومات وحتى تاريخ إعلان نتيجة عرض الشراء في ضوء المادتين (330 و343) من اللائحة التنفيذية لقانون سوق رأس المال.

وفي جميع الأحوال، يجب مراعاة قبل دعوة الجمعية العامة غير العادية بغرض زيادة رأس المال على شرائح لإصدار، أن تتضمن المستندات المقدمة للهيئة دراسة استخدامات أموال الزيادة لاستخدامات أموال الزيادة.$t64b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins63;

WITH ins64 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 49, 0, NULL, $t65a$مادة 49$t65a$, $t65b$مع عدم الإخلال بأحكام المادة (48) من هذه القواعد، تتولى الهيئة دراسة طلب الشركة بنشر تقرير الإفصاح بغرض السير في إجراءات تعديل القيمة الاسمية للأسهم في ضوء المعايير التالية:

أولاً: المعايير الكيفية
1- مدى الالتزام بقواعد الحوكمة المنصوص عليها بهذه القواعد.
2- نتائج اعمال الشركة التاريخية قبل تقديم طلب التعديل.
3- عدم وجود تحركات سعرية غير مبررة على سهم الشركة خلال الشهر السابق لنشر ملخص قرار مجلس إدارة الشركة باعتماد تقرير الإفصاح بغرض السير في تعديل القيمة الاسمية.

ثانياً: المعايير الكمية
1- نسبة الأسهم حرة التداول للشركة مقارنة بمتوسط نسبة الأسهم حرة التداول على مستوى القطاع وعلى مستوى السوق.
2- معدل دوران الأسهم حرة التداول للشركة مقارن بمتوسط معدل دوران الأسهم حرة التداول على مستوى القطاع والسوق، وعلى أن يحسب معدل دوران الأسهم حرة التداول من خلال قسمة الأسهم المتداولة بعد استبعاد المعاملات غير المعتادة إلى عدد الأسهم حرة التداول عن أخر الثلاثة أشهر السابقة على كل شهر مقيدة.
3- السعر السوقي المقترح للتعديل مقارن بسعر الاغلاق بالجنيه المصري الذي لا يقل عنه من عدد الشركات المقيدة في الشهر السابق.

وتصدر الهيئة موافقتها على نشر تقرير الإفصاح بغرض السير في إجراءات تعديل القيمة الاسمية في ضوء دراسة مبررات وأسباب تعديل القيمة الاسمية وأثر ذلك على حقوق المساهمين واستقرار التعاملات.

في جميع الأحوال لا يجوز أن تقوم الشركة بتعديل القيمة الاسمية لأسهمها لمرة واحدة إلا خلال أثني عشر شهراً من تاريخ آخر تعديل للقيمة الاسمية بالبورصة.$t65b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins64;

WITH ins65 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 50, 0, NULL, $t66a$مادة 50$t66a$, $t66b$مع مراعاة أحكام المواد (151، 151 مكرر، 152، 152 مكرر) من اللائحة التنفيذية للقانون 159 لسنة 1981 يلتزم مجلس إدارة الشركة في حالة رغبته في تطبيق نظام لإثابة أو تحفيز العاملين والمديرين من خلال تملك أسهم، أو الوعد ببيع أسهم، إتباع الإجراءات الآتية:

1- التقدم للهيئة بطلب الموافقة على نشر تقرير الإفصاح بغرض السير في دعوة الجمعية العامة غير العادية للشركة لإقرار نظام الإثابة والتحفيز على النموذج المعد لذلك بالهيئة مرفقاً به موافقة مجلس إدارة الشركة على اعتماد تقرير الإفصاح وكافة المستندات المؤيدة وذلك خلال يومي عمل من تاريخ انعقاد المجلس.
2- التقدم للبورصة لنشر تقرير الإفصاح على شاشة إعلانات وموقعها الالكتروني فور صدور ممانعة الهيئة ولا يتم السير في إجراءات الدعوة للجمعية العامة غير العادية لانعقاد الجمعية إلا بعد نشر هذا التقرير.
3- الدعوة لاجتماع الجمعية العامة غير العادية للشركة للنظر في إقرار النظام خلال أسبوع من تاريخ نشر تقرير الإفصاح على شاشات الاعلانات بالبورصة.
4- التزام الشركة بنشر ملخص بيان أهم بنود التحفيز والاثابة المزمع تطبيقه فور اعتماده من الهيئة بصورة نهائية على الهيئة.

ويلتزم مجلس إدارة الشركة باتباع الإجراءات ذاتها المشار إليها في حال الرغبة في تعديل أي من الإجراءات المذكورة إليها بالبند السابق في حال الرغبة في أي من تلك النظم.$t66b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins65;

WITH ins66 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 51, 0, NULL, $t67a$مادة 51$t67a$, $t67b$تلتزم الشركة التي ترغب في شراء أو بيع من جانب أسهمها (أسهم الخزينة) أن تخطر البورصة مسبقاً برغبتها في ذلك على النموذج المعد المعتمد من الهيئة والبورصة، على أن يُرفق بالإخطار محضر اجتماع مجلس إدارة الشركة المتضمن قرار الشراء أو البيع قبل بدء التنفيذ، وبمراعاة الضوابط الآتية:

1- أن تكون الأسهم المراد شرائها في صورة أسهم محلية.
2- ألا تقل مدة احتفاظ الشركة بأسهم الخزينة عن ثلاثة أشهر ولا تزيد على سنة ميلادية من تاريخ التنفيذ وإلا وجب عليها التخفيض بمقدار القيمة الاسمية لتلك الأسهم وباتباع الإجراءات المقررة لذلك وفقاً للقانون رقم (159) لسنة 1981 ولائحته التنفيذية والقانون رقم (95) لسنة 1992 ولائحته التنفيذية.
3- ألا تتجاوز نسبة أسهم الخزينة نسبة (10%) من إجمالي أسهم الشركة المقيدة.
4- ألا يؤدي شراء الشركة لأسهم الخزينة إلى انخفاض نسبة الأسهم حرة التداول بالشركة عن الحد الأدنى المنصوص عليه بهذه القواعد.
5- أن يتم شراء أو بيع أسهم الخزينة من خلال أي من الطريقتين الآتيتين:
(أ) من خلال السوق المفتوح وفقاً للضوابط الآتية:
- ألا تتجاوز فترة تنفيذ عملية الشراء أو البيع مدة شهر من الأحوال وفي حالة عدم الإخطار مدة شهر من تاريخ الإخطار وفي حالة عدم إتمام تنفيذ ما نسبته 50% من الكمية المطلوب شرائها خلال تلك المدة، لا يجوز التقدم بطلب لشراء أسهم خزينة مرة أخرى قبل مضي ثلاثة أشهر أخرى من قبل التنفيذ السابق إلا إذا قدمت الشركة مبررات تقبلها البورصة.
- اقتصار تعامل وإدراج الأوامر لأسهم الخزينة على جلسة التداول الأساسية دون الجلسات الاستكشافية وجلسة مزاد الإغلاق.
- لا يجوز اشتراك الداخليين بما فيهم أعضاء مجلس إدارة الشركة ومجموعاتهم المرتبطة والشركات التابعة والشقيقة وأسهمهم في الشركة خلال فترة تنفيذ الشركة لعملية شراء أسهم الخزينة ويستثنى من ذلك عمليات البيع الجبري وعمليات البيع التي تتم بسبب شطب أسهم الشركة.
(ب) من خلال سوق الصفقات الخاصة وفقاً للضوابط الآتية:
- أن يتم تنفيذ العملية خلال خمسة أيام عمل ويجوز مدها بناءً على مبررات تقبلها البورصة.
- لا يجوز اشتراك الداخليين بما فيهم أعضاء مجلس إدارة الشركة ومجموعاتهم المرتبطة والشركات التابعة والشقيقة وأسهمهم في الشركة خلال فترة تنفيذ الشركة لعملية شراء أسهم الخزينة.
6- على الشركة تمويل عملية الشراء من خلال مواردها الذاتية ولا يجوز لها تمويلها عن طريق الاقتراض، ويجب على الشركة إرفاق إخطار الشراء بإقرار من الممثل القانوني للشركة أو تقرير حديث من مراقب حساباتها يفيد توافر الموارد المالية لديها لشراء أسهم الخزينة.

وتلتزم الشركة بالإفصاح للبورصة بنسبة ما تم تداوله أو شراؤه من أسهم الخزينة بنهاية كل يوم تداول تم فيه التنفيذ، وتقوم البورصة بنشر ذلك الإفصاح بالوسائل المعدة لديها.

وفي جميع الأحوال، ومع عدم الإخلال بحكم المادتين (356، 356 مكرراً) من اللائحة التنفيذية لقانون سوق رأس المال، يجب على المساهم والأشخاص المرتبطة به في حال تجاوز النسب الموجبة لتقديم عرض شراء إجباري وفقاً لأحكام الباب الثاني عشر من اللائحة التنفيذية، الامتناع عن التصويت بنسبة الأسهم المتجاوزة على الموضوعات المعروضة في اجتماعات الجمعية العامة للشركة وكذلك عدم زيادة نسبة تملك تلك الأسهم على ذلك ما لم يتم التقدم بعرض الشراء الاجباري أو الاستثناء منه.$t67b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins66;

WITH ins67 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 51, 1, NULL, $t68a$مادة 51 مكرر$t68a$, $t68b$في حالة شراء الشركة أسهم خزينة من خلال شركة تابعة خاضعة للسيطرة الفعلية لها تعد الأسهم المشتراه لها بمثابة أسهم خزينة وتسري عليها كافة الأحكام الخاصة بأسهم الخزينة.

وتلتزم الشركات المقيد لها أسهم بالبورصة بأن يكون التصرف في تلك الأسهم أسهم خزينة للغير خلال سنة من الأكثر من تاريخ حصولها عليها، ولا يعتبر في حكم الغير قيام الشركة بالتصرف في هذه الأسهم لشركة تابعة لها أو خاضعة أو خاضعة لسيطرتها الفعلية.

ويقصد بالسيطرة الفعلية المفهوم الوارد بالمادة (44 مكرراً) من هذه القواعد.

ويجوز بقرار من الجمعية العامة غير العادية للشركة ذات غرض الاستحواذ فتح حساب مؤقت يسمى "حساب الاسترداد" يتم تكويده بالبورصة المصرية لشراء أسهم المساهمين المتضررين من عمليات الاستحواذ، ويتم تمويل هذا الحساب من خلال المادة (7 مكرراً) من هذه القواعد إذا لم تنفذ الشركة الاستحواذ خلال السنتين المشار إليهما بالمادة (7 مكرراً) من هذه القواعد بتخفيض رأسمالها بهذه الأسهم أو إعادة طرح هذه الأسهم على مستثمرين آخرين مؤهلين وفقاً للتعريف الوارد بقرار مجلس إدارة الهيئة رقم (177) لسنة 2023 المشار إليه، وذلك بعد موافقة الجمعية العامة غير العادية للشركة على خطة جديدة للاستحواذ على شركة جديدة للاستحواذ عليها الشركة، ويسري في شأن حساب الاسترداد أحكام الفقرة الثانية من المادة (55 مكرراً).$t68b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins67;

WITH ins68 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 51, 2, NULL, $t69a$مادة 51 مكرر 1$t69a$, $t69b$يجوز للشركة المقيد لها أسهم بالبورصة التصرف بالتنازل لمساهميها عن أسهم الخزينة التي لم يمر على شرائها عام ميلادي كأسهم مجانية، وذلك بمراعاة الضوابط الآتية:

1- صدور قرار من الجمعية العامة للشركة بالموافقة على التصرف في أسهم الخزينة عنها بالتنازل للمساهمين مجانية، على أن يتم الحصول على موافقة الهيئة على دعوة الجمعية العامة المسبقة لاتخاذ قرار بذلك والاعفاء من سداد المقابل النقدي لتنفيذ عملية التنازل المشار إليها.
2- ألا تقل الفترة الزمنية من تاريخ الجمعية العامة العادية وحتى نهاية السنة الميلادية المحتسبة من تاريخ شراء أسهم الخزينة المحدد للزيادة وذلك يوم عمل قبل انقضاء مدة السنة المشار إليها.
3- اتباع إجراءات ذات إعلانات توزيعات الأسهم المجانية وضوابط التنفيذ المنصوص عليها بالمادة (33) من هذه القواعد.

ويتم إجراء عملية التنازل لمساهمي الشركة عن أسهم الخزينة وفقاً للضوابط والإجراءات التنفيذية التي تحددها البورصة بالتنسيق مع شركة الإيداع المركزي والقيد بعد اعتمادها من الهيئة.$t69b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins68;

WITH ins69 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 52, 0, NULL, $t70a$مادة 52$t70a$, $t70b$تلتزم الشركة المقيد لها أسهم بالبورصة في جميع حالات الزيادة النقدية لرأس المال بإعمال حقوق الأولوية لقدامى المساهمين ما لم تقرر الجمعية العامة غير العادية للشركة التنازل عن إعمال حقوق الأولوية عند زيادة رأس المال وبمراعاة حكم المادة (32) من اللائحة التنفيذية لقانون سوق رأس المال.

ويتم إعداد إعلان الزيادة على النموذج المعد لذلك بالهيئة بعد التنسيق مع البورصة وشركة مصر للمقاصة.

ويجب أن يتضمن الإعلان كافة البيانات الواجب النص عليها في نشرة الاكتتاب العام لزيادة رأس المال.

وعلى الشركة إخطار البورصة بالدعوة عن زيادة رأس المال مع إعمال حقوق الأولوية للمساهمين القدامى وذلك فور اعتماده من الهيئة وقبل النشر ويجب أن يتضمن ذلك موعد اعتماد اكتتاب الأولوية القدامى المساهمين وتاريخ تداول حق الأولوية في الاكتتاب منفصلاً عن السهم الأصلي.

وعلى الشركة نشر الإعلان المعتمد من الهيئة للدعوة للاكتتاب مع إعمال حق الأولوية في زيادة رأس المال للمساهمين القدامى في جريدتين يوميتين صباحيتين واسعتي الانتشار وذلك قبل تاريخ نشر ذلك الإعلان بأسبوع على الأكثر على تاريخ اعتماده من الهيئة متضمناً تاريخ آخر يوم لتداول السهم الأصلي محمل بحق الأولوية في الاكتتاب.

وبالنسبة الأولوية الزمنية فور نشر إعلان دعوة قدامى المساهمين للاكتتاب، تلتزم الشركة بألا تقل الفترة الزمنية من تاريخ نشر الإعلان حتى أخر يوم لتداول السهم الأصلي محمل بحق الأولوية في الاكتتاب عن سبعة أيام.

وبمراعاة حكم الفقرة الأولى، تلتزم الشركة فور نشر إعلان دعوة قدامى المساهمين للاكتتاب في زيادة رأس مالها بتقديم طلب للبورصة لقيد حقوق الأولوية في الاكتتاب وذلك قبل أسبوع من التاريخ المحدد لفتح باب الاكتتاب. على أن ترفق بطلبها كافة المستندات المطلوبة ويصدر بالقيد قرار من لجنة القيد بالبورصة.$t70b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins69;

WITH ins70 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 52, 1, NULL, $t71a$مادة 52 مكرر$t71a$, $t71b$يتم تداول حق الأولوية في الاكتتاب منفصلاً عن السهم الأصلي في الفترة من تاريخ قيد حق الأولوية وحتى يوم عمل قبل نهاية فترة الاكتتاب وفقاً لقواعد التداول المعتمدة من الهيئة.

ويشطب قيد حق الأولوية في الاكتتاب ويحذف من قاعدة بيانات التداول من على قاعدة بيانات التداول عقب انتهاء فترة الاكتتاب.

ويلتزم مجلس إدارة الشركة التي تم قيد زيادة رأسمالها المصدر المقومة نقداً بصورة سنوية نصف سنوية وفقاً للنموذج المعد لذلك عن تفاصيل حصيلة استخدام زيادة رأس المال وذلك في ذات التوقيتات الخاصة بالإفصاح عن القوائم المالية.$t71b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins70;

WITH ins71 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 53, 0, NULL, $t72a$مادة 53$t72a$, $t72b$يتم النظر في شطب الأوراق المالية المقيدة وذلك متى توافرت في شأنها حالة أو أكثر من الحالات الآتية:

1- إذا تبين أن القيد تم على أساس بيانات غير صحيحة تؤثر في سلامة القيد.
2- إذا لم تقم الشركة بالوفاء بالتزاماتها والإفصاح وفقاً لأحكام هذه القواعد بعد انقضاء شهر من إخطارها من قبل البورصة حسب الأحوال.
3- إذا طلبت الأوراق المالية الأجنبية المقابلة لشهادات الإيداع المصرية.
4- إذا مضت ستة أشهر دون عقد تداول متصلاً ولا يعد تطبيق هذا البند من التداولات التي تتم بين أشخاص المجموعة المرتبطة أو بين الأطراف ذات العلاقة أو غيرها من العمليات الصورية.
5- إذا لم تقم الشركة بسداد رسوم القيد المقررة.
6- إذا خالفت الشركة أحد أحكام قواعد عرض القوائم المالية واستمراره وفقاً لمعايير المحاسبة المصرية والافصاح عنها للبورصة مع عدم الاخلال بحكم المادة (53 مكرراً) من هذه القواعد.

وعلى إدارة البورصة مخاطبة رئيس مجلس الشركة بأوجه الإخلال المشار إليها بالفقرة السابقة، وتلتزم الشركة بتصحيح المخالفات المنسوبة لها خلال المدة التي تحددها البورصة، ويجوز مدها بناءً على مبررات تقدمها الشركة وتقبلها البورصة وفي حالة انقضاء تلك المدة دون قيام الشركة بإزالة المخالفات، يتم عرض موقفها على لجنة القيد لإصدار قرار بشأنها، على أن تقوم البورصة بإخطار الشركة بقرار اللجنة في اليوم العمل التالي لصدور القرار.

ويجوز للجنة قيد الأوراق المالية إرجاء النظر في إصدار قرار بالسير في إجراءات شطب أسهم قيد الشركة، وذلك حال وجود مقدم شراء على أسهم الشركة، ولمدة تحددها اللجنة وفقاً لتقديرها شريطة توافر ما يأتي:

1- أن يتعهد مقدم عرض الشراء على استمرار المحافظة على قيد أسهم الشركة بالبورصة المصرية.
2- التزام مقدم عرض الشراء بإعداد دراسة عادلة لسعر السهم معدة من مستشار مالي مستقل مسجل لدى الهيئة.
3- تقديم مقدم العرض خطة عمل مستقبلية، تعرض على كل من الهيئة والبورصة، تتضمن الإجراءات المقترحة لتصحيح المخالفات القائمة، وتحسين وتطوير الأداء التشغيلي والمالي للشركة، وذلك خلال إطار زمني محدد.

ومع عدم الإخلال بأحكام الباب الثاني عشر من اللائحة التنفيذية لقانون سوق رأس المال، في حال عدم إتمام عرض الشراء خلال المدة التي حددها لجنة القيد بالسير في إجراءات عرض الشراء لأسهمها، يُعاد عرض موقف الشركة على اللجنة لاتخاذ قرارها في إجراءات شطب أسهمها من البورصة المصرية.

وبمراعاة أحكام البند (8) من المادة (7) والبند (7) من المادة (9) والفقرة (هـ) من المادة (15) من هذه القواعد يجوز للبورصة شطب أسهم الشركة إذا فقدت أياً من معياري الحد الأدنى لصافي الربح وحقوق المساهمين بحسب الأحوال منذ سنتين ماليتين متتاليتين بعد القيد.

وفي جميع الأحوال، تلتزم الشركة في حال شطب قيد أسهمها بالبورصة إجبارياً من قبل شرائها بشراء أسهم مساهمي الأقلية والأقلية الاجبارياً من شراء أسهم مساهمي الأقلية والأقلية المكتتبين في أسهم الزيادة المكتتبين في أسهم الزيادة "SPECIAL PURPOSE ACQUISITION COMPANY (SPAC)" والراغب مالكيها في البيع - أو ضمان قيام الغير بهذا الشراء - على ألا يتم تنفيذ هذا الشراء خلال ثلاثة أشهر على الأكثر من تاريخ إخطار اللجنة بقرارها في إجراءات الشطب بالسير في إجراءات شطب بسعر لا يقل عن القيمة العادلة التي يحددها مستشار مالي مستقل لدى المقيدين لدى الهيئة لهذا الغرض، كما يجوز لأي شخص تكون له الأسهم حرة التداول مرهونة أن يبيع أسهم الشركة المرهونة له وفقاً لأحكام هذه الفقرة.

وللهيئة في حالة تقاعس الشركة عن تنفيذ التزامها المبين بالفقرة السابقة، تكليف مستشار مالي مستقل لديها لإعداد دراسة عادلة قيمة عادلة وإلزام الشركة بإتاحة البيانات اللازمة للدراسة.

ويجوز النظر في شطب الأوراق المالية المصدرة للشركات قيد الأسهم المصدرة للشركات تحت التصفية في أي مرحلة من مراحل التصفية دون التقيد بالأحكام المنصوص عليها في الفقرة الرابعة من هذه المادة.

وفي جميع الأحوال يتم شطب الأوراق المالية بقرار مسبب من لجنة قيد الأوراق المالية بالبورصة، على أن يسري قرار الشطب من التاريخ المحدد بقرار اللجنة بالشطب.

وتقوم البورصة بالإفصاح على شاشات الاعلانات وعلى موقعها الالكتروني بكافة المخاطبات والقرارات الخاصة بتطبيق هذه المادة.$t72b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins71;

WITH ins72 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 53, 1, NULL, $t73a$مادة 53 مكرر$t73a$, $t73b$في الأحوال التي تفقد فيها إحدى الشركات المقيد أسهمها بالبورصة أحد شروط القيد واستمرار القيد التالية (نسبة الأسهم حرة التداول -نسبة التداول -عدد المساهمين -عدد الأسهم المقيدة)، فعلى البورصة مخاطبة هذه الشركات خلال شهر على الأكثر من تاريخ تحقق عدم الاستيفاء.

وعلى الشركة موافاة البورصة خلال شهرين على الأكثر بمخاطبتها بخطة زمنية لا تتعدى مدة تنفيذها ستة أشهر تتعهد فيها الشركة باستيفاء تلك الشروط، ويجوز مد هذه المهلة بناء على طلب تقدمه الشركة بطلب على مبررات التأخير وتقبله الهيئة.

وفي حال عدم تلقي البورصة رد متضمناً الخطة الزمنية المطلوبة لاستيفاء هذه الشروط أو عدم قيام الشركة باستيفاء هذه الشروط وفقاً لأحكام الفقرة السابقة يعرض موقف الشركة خلال شهر على الأكثر من انتهاء المدة المحددة بالفقرة السابقة على لجنة القيد بالبورصة لإصدار قرار بالسير في إجراءات شطب قيد أسهمها من البورصة، وذلك بمراعاة أحكام المادة (53) من هذه القواعد.

كما تشطب أسهم الشركات ذات غرض الاستحواذ في أي من الحالتين الآتيتين:

1- عدم صدور قرار من الجمعية العامة غير العادية للشركة بالموافقة على الاستحواذ على الشركات أو الشركات المستهدفة خلال ستة أشهر من تاريخ قيد أسهم الشركة بالبورصة، ما لم توافق الهيئة على مد المهلة في ضوء مبررات تقبلها.
2- إذا لم يتم تنفيذ الاستحواذ على الشركة أو الشركات المستهدفة خلال سنتين من تاريخ قيد أسهم الشركة بالبورصة المصرية، ما لم توافق الهيئة على مد المهلة في ضوء مبررات تقبلها.$t73b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins72;

WITH ins73 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 54, 0, NULL, $t74a$مادة 54$t74a$, $t74b$يجوز للشركة أو لمالكي أوراقها المالية (5% فأكثر) تقديم طلب إعادة نظر في قرار شطب القيد الصادر في اللجنة أمام مجلس إدارة البورصة على شاشات الشطب على شاشات البورصة بالقرار، وعلى المجلس البت في الطلب في أول جلسة انعقاد له تالية لتاريخ تقديمه مستوفياً.

وفي حالة تأييد مجلس إدارة البورصة لقرار لجنة القيد لقرار الشطب يجوز للشركة تقديم التماس للهيئة خلال خمسة عشر يوماً من تاريخ الإخطار بقرار مجلس إدارة البورصة، وتقوم الهيئة بالبت في الالتماس خلال خمسة عشر يوماً من تاريخ تقديمه مستوفياً.$t74b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins73;

WITH ins74 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 55, 0, NULL, $t75a$مادة 55$t75a$, $t75b$يجوز شطب الأوراق المالية المقيدة بناءً على طلب من الجهة أو الشركة المصدرة بقرار من لجنة القيد المصدرة بقرار من لجنة القيد بعد التأكد من القيام بالإجراءات الآتية:

1- قيام الممثل القانوني للشركة الراغبة في الشطب الاختياري لأوراقها المالية بالتقدم للهيئة بطلب الموافقة على نشر تقرير إفصاح بغرض السير في إجراءات دعوة الجمعية العامة غير العادية للشركة للنظر في الشطب الاختياري وشراء أسهم مالكي أسهم المتضررين مرفقاً بالطلب المستندات المؤيدة للطلب فيما يتضمن مبررات الشطب الاختياري والدعوة للجمعية العامة غير العادية للشركة للنظر في الشطب الاختياري بسجلات محضر اجتماع مجلس الإدارة المتضمن اعتماد قرار الإفصاح الموضح به مبررات الشطب الاختياري من العمل خلال يومي عمل من تاريخ انعقاد المجلس.
2- نشر تقرير الإفصاح المشار إليه على شاشات إعلانات البورصة فور صدور موافقة الهيئة عليه.
3- الدعوة لاجتماع الجمعية العامة غير العادية للشركة للنظر في الشطب الاختياري وشراء أسهم مساهمي الأقلية المتضررين خلال أسبوع من تاريخ نشر تقرير الإفصاح.
4- صدور قرار من الجمعية العامة غير العادية للشركة بأغلبية (75%) على الأقل من الأسهم الحاضرة من الأسهم الحاضرة للاجتماع بالموافقة على شطب قيد أسهم الشركة وشراء أسهم المتضررين، وفي حالة الدراسة إذا أسفرت مجموعة مسيطرة على مساهم بمفرده أو أكثر من مجموعتهم المرتبطة على قرارات الجمعية العامة العادية والجمعية العامة يكون التصويت على قرار الشطب المشار إليه على النحو التالي:
أ- تصويت جميع المساهمين الحاضرين بالاجتماع وموافقة 75% على الأقل من تلك الأسهم.
ب- تصويت مساهمي الأقلية - غير المرتبطين بالمساهمين المسيطرين - الحاضرين للاجتماع وموافقة أغلبية أسهمهم.

ويصدر القرار بالموافقة على الشطب وشراء أسهم المتضررين إذا تحققت نسب الموافقة المنصوص عليها بالبند (أ) و(ب) مجتمعين.
5- ويلزم أن يتضمن قرار الجمعية العامة غير العادية بالشطب الموافقة على عرض شراء أسهم المتضررين بأسعار القيمة التالية بأعلى القيم التالية: أعلى سعر إقفال أسهم الشركة خلال الشهر السابق على قرار مجلس الإدارة بالسير بدعوة تلك الجمعية، أو متوسط أسعار إقفال أسهم الشركة خلال الثلاثة أشهر السابقة أشهر السابقة على تاريخ صدور قرار المجلس بدعوة تلك الجمعية، أو القيمة العادلة للسهم المحددة من قبل مستشار مالي مستقل من المقيدين لدى الهيئة، على أن يفصح عن دراسة القيمة العادلة قبل انعقاد الجمعية العامة للسهم بخمسة عشر يوماً على الأقل.
6- عدم تضرر أي طرف آخر تكون الأسهم محل الشطب مرهونة له ضماناً لدين له، وفي حالة تضرر مصلحته من بيع حقه على أن يعاد الأسهم المرهونة يكون له حقه على أن يعاد الأسهم المرهونة يكون رهن ما تم استيفاء الرهن وفقاً لما تضمنه عقد الرهن المرهونة وفقاً لذات الأحكام الواردة بالبند السابق.
7- ويلزم أن تتقدم الشركة بمستندات شطب القيد للبورصة خلال خمسة أيام عمل من تاريخ قرار الجمعية العامة المشار إليه، وعلى أن يتم الانتهاء من استيفاء مستندات الشطب بحد أقصى 20 يوم عمل من تاريخ استيفاء مستندات الشطب لدى البورصة، ويجوز أن يتم تنفيذ عمليات شراء أسهم المتضررين بصورة يومية وفقاً للقواعد المعمول بها بالبورصة.
8- بالنسبة للشركات الناتجة عن إعادة الهيكلة بالتقسيم سواء القاسمة أو المنقسمة والتي لا يتوافر بشأنها شروط استمرار القيد و/أو المعايير المالية للقوائم المالية الافتراضية بعد التقسيم يلزم أن يتضمن قرار الجمعية العامة غير العادية بالتقسيم إلزام الشركة القاسمة بشراء أسهم المساهمين المتضررين من التقسيم وفقاً للحكم الوارد بالبند (5) من هذه المادة.

وفي حال عدم التزام الشركة القاسمة بتنفيذ الشطب وشراء أسهم المتضررين، يستمر تداول الورقة المالية لمدة لا تتجاوز ثلاثة أشهر من تاريخ صدور قرار الجمعية العامة غير العادية بالتقسيم، ثم يعرض موقف الشركة على لجنة القيد بالبورصة لإصدار قرار بشطب الورقة المالية إجبارياً مع إلزام الشركة القاسمة بشراء أسهم المتضررين من الشطب وذلك وفقاً لأعلى القيم المنصوص عليها بالبند (5) من هذه المادة.$t75b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins74;

WITH ins75 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 55, 1, NULL, $t76a$مادة 55 مكرر$t76a$, $t76b$يجوز للشركات المقيد أسهمها في البورصة المصرية مع موافقة الجمعية العامة غير العادية أن تنشئ حساباً مؤقتاً للتعامل يسمى "حساب أسهم الشطب" يقتصر غرضه على تنفيذ عمليات شراء أسهم المساهمين المتضررين من الشطب، على أن يتم تمويل هذا الحساب من خلال الشركة دون ضمان من الغير.

وتسري أحكام أسهم الخزينة على أسهم هذا الحساب عدا الحد الأقصى لنسبة أسهم الخزينة الأقصى الأسهم الخزينة لإجمالي أسهم الشركة المصدرة.$t76b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins75;

WITH ins76 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 56, 0, NULL, $t77a$مادة 56$t77a$, $t77b$يجوز للشركات التي تم شطب قيد أسهمها إجبارياً تقديم طلب قيد جديد عند استيفائها متطلبات وشروط القيد وبمراعاة تقديم قوائمها المالية عن سنتين ماليتين تاليتين لتاريخ الشطب لتاريخي الشطب إذا كان الشطب تم لمخالفة متطلبات الإفصاح.

ويجوز للشركة التي تم شطب قيد أسهمها إجبارياً لمخالفة الإفصاح المقيد أو التي شطب قيد أسهمها اختيارياً، تقديم طلب قيد جديد بشرط استيفائها متطلبات القيد وشروط الإفصاح، وذلك بعد تقديمها قوائمها المالية عن سنة مالية تالية لتاريخ الشطب.$t77b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins76;

WITH ins77 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 57, 0, NULL, $t78a$مادة 57$t78a$, $t78b$على كل شركة مقيد لها أوراق مالية بجداول البورصة الالتزام بكافة الأحكام الواردة بهذه القواعد في تاريخ العمل بهذه القواعد، وذلك مع مراعاة ما يلي:

أولاً: تلتزم الشركات بتوفيق أوضاعها للنسب الواردة بهذه القواعد والخاصة بنسبة الأسهم المطروحة ونسبة الأسهم حرة التداول وذلك بحد أقصى 2014/12/31 وإلا تم شطبها.

ثانياً: تستثنى الشركات المقيد لها أوراق مالية بجداول البورصة في تاريخ العمل بهذه القواعد مما يلي:
أ. البند (6) من المادة (7) بشأن الحد الأدنى لرأس مال الشركة المطلوب قيد أسهمها.
ب. البند (7) من المادة (7) بشأن نسبة الأسهم الواجب الاحتفاظ بها.
ج. البند (9) من المادة (8) بشأن نسبة الأسهم الواجب الاحتفاظ بها.

وذلك دون الإخلال بالحد الأدنى لرأس مال الشركة الواجب الاحتفاظ به وفقاً للضوابط الواردة في القواعد التي تم بموجبها قيد أسهم الشركة.$t78b$
  FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2014-01-22', 'active' FROM ins77;

-- ===== التحقق النهائى =====
DO $verify065$
DECLARE
  v_law_id uuid;
  v_article_count int;
  v_version_count int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 11 AND law_year = 2014 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN RETURN; END IF;

  SELECT count(*) INTO v_article_count FROM articles WHERE law_id = v_law_id;
  SELECT count(*) INTO v_version_count FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id;

  RAISE NOTICE '[065] decision 11/2014: % صف و% نسخة بعد الهجرة.', v_article_count, v_version_count;

  UPDATE laws SET governance_scope = true, enacted_at = COALESCE(enacted_at, '2014-01-22')
  WHERE id = v_law_id;
END
$verify065$;

COMMIT;
